/* Généré par scripts/construire-pelvis.js — ne pas modifier à la main.
   Index de recherche de la section Pelvis : une entrée par fiche
   (t : titre, n : nom dans la page du chapitre, u : adresse depuis pelvis/, c : chapitre, b : En bref,
   s : sections { i : ancre, t : titre, x : texte }). */
window.PelvisRecherche = [{"t":"Radio-anatomie de l'ovaire","n":"Radio-anatomie","u":"ovaire/radio-anatomie.html","c":"Ovaire","b":"l'aspect normal de l'ovaire dépend de l'âge et du moment du cycle. Le reconnaître évite de prendre un follicule ou un corps jaune pour une lésion.","s":[{"i":"situation-et-moyens-de-fixite","t":"Situation et moyens de fixité","x":"Organe intrapéritonéal, dans la fossette ovarienne, en arrière du ligament large, sous les vaisseaux iliaques externes. Ligament suspenseur (lombo-ovarien), qui contient le pédicule ovarien ; ligament utéro-ovarien ; mésovarium. Position variable : l'ovaire peut se trouver dans le cul-de-sac de Douglas ou au-dessus de l'utérus, surtout s'il est augmenté de volume."},{"i":"vascularisation","t":"Vascularisation","x":"Artère ovarienne : naît de l'aorte sous les artères rénales, s'anastomose avec l'artère utérine (double vascularisation). Veine ovarienne : longe le psoas, se draine dans la veine cave inférieure à droite et dans la veine rénale gauche à gauche. Repère pratique : suivre le pédicule ovarien jusqu'à une masse prouve son origine ovarienne ou annexielle."},{"i":"aspect-selon-la-periode","t":"Aspect selon la période","x":"Période · Échographie · IRM Activité génitale, phase folliculaire · Follicules antraux < 10 mm ; un follicule dominant grossit jusqu'à environ 20–25 mm avant l'ovulation · Follicules en hypersignal T2 dans un stroma de signal plus bas Phase lutéale · Corps jaune : kyste à paroi épaisse et festonnée, contenu parfois échogène, vascularisation périphérique annulaire au Doppler · Paroi épaisse qui se rehausse, contenu de signal variable Ménopause · Ovaire petit, homogène, peu ou pas de follicules ; petits kystes simples fréquents · Stroma en hyposignal T2, rares follicules"},{"i":"a-retenir","t":"À retenir","x":"Corps jaune : diamètre < 25 mm ; au-delà, on parle de kyste lutéal hémorragique. Le comptage des follicules antraux se fait à J3 du cycle."},{"i":"pieges","t":"Pièges","x":"Une vascularisation annulaire péri-utérine n'est pas toujours un corps jaune : grossesse extra-utérine, abcès tubo-ovarien, myome sous-séreux pédiculé. Doser les βhCG en cas de doute. Un corps jaune hémorragique peut avoir un contenu échogène hétérogène : ne pas le confondre avec une portion tissulaire, car il n'est pas vascularisé à l'intérieur."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille des deux ovaires, présence de follicules et d'un corps jaune, toute lésion avec sa latéralité, sa taille et son score O-RADS."}]},{"t":"Kystes fonctionnels","n":"Kystes fonctionnels","u":"ovaire/kystes-fonctionnels.html","c":"Ovaire","b":"chez la femme non ménopausée, un kyste uniloculaire à paroi fine est presque toujours fonctionnel et régresse spontanément en quelques semaines.","s":[{"i":"terrain","t":"Terrain","x":"Femme en période d'activité génitale. Un kyste hémorragique après la ménopause est inhabituel et doit faire reconsidérer le diagnostic."},{"i":"imagerie","t":"Imagerie","x":"Kyste folliculaire (follicule dominant qui ne s'est pas rompu) Échographie : kyste uniloculaire, anéchogène, paroi fine, renforcement postérieur, sans cloison ni végétation. IRM : franc hypersignal T2, hyposignal T1, paroi fine. Corps jaune et kyste lutéal hémorragique (saignement dans un corps jaune ; kyste lutéal hémorragique au-delà de 25 mm) Échographie : contenu échogène hétérogène en « filet de pêche » (cloisons de fibrine mobiles et avasculaires), parfois caillot aux bords concaves ; couronne d'hypervascularisation en Doppler. IRM : iso- ou hypersignal T1 inférieur à la graisse (contrairement à l'endométriome), signal T2 variable ; hypervascularisation annulaire périphérique (rehaussement pariétal, hypersignal diffusion de la paroi)."},{"i":"signes-cles","t":"Signes clés","x":"Un caillot se déforme sous la sonde, n'est pas vascularisé et a des bords concaves ; une végétation est convexe et peut être vascularisée. Le kyste hémorragique évolue en quelques semaines : son aspect change au contrôle."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kyste à contenu échogène : endométriome, tératome mature, abcès tubo-ovarien, tumeur mucineuse. Kyste simple qui persiste : cystadénome séreux ; aucun signe d'imagerie ne le distingue d'un kyste folliculaire, seule l'évolution le fait. Kyste para-ovarien ou para-tubaire : kyste simple séparé de l'ovaire, qui bouge indépendamment de lui sous la sonde (O-RADS 2, pas de surveillance)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Situation · Conduite Kyste liquidien pur, femme non ménopausée · Kyste fonctionnel entre 3 et 5 cm : contrôle échographique optionnel à 6–12 semaines Kyste liquidien pur, femme ménopausée · À considérer comme une lésion organique au-delà de 1 cm Kyste liquidien pur > 7 cm · IRM Kyste lutéal hémorragique < 5 cm · Pas de contrôle Kyste lutéal hémorragique > 5 cm · Contrôle échographique éventuel à 6–12 semaines"},{"i":"pieges","t":"Pièges","x":"Ne pas décrire comme « portion tissulaire » un caillot ou un réseau de fibrine non vascularisés. Aucun critère d'imagerie ne distingue un kyste folliculaire d'un cystadénome séreux bénin : seule la régression spontanée tranche."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, contenu, paroi, absence de portion tissulaire et de flux interne, statut ménopausique et conduite proposée."}]},{"t":"Rupture et hémorragie de kyste","n":"Rupture et hémorragie de kyste","u":"ovaire/rupture-hemorragie-kyste.html","c":"Ovaire","b":"douleur pelvienne aiguë + kyste ovarien + épanchement : on juge la gravité sur l'abondance de l'hémopéritoine, après avoir éliminé une grossesse extra-utérine.","s":[{"i":"terrain","t":"Terrain","x":"Femme jeune, souvent en deuxième partie de cycle (corps jaune) ; facteurs favorisants : rapport sexuel, traumatisme, anticoagulants."},{"i":"imagerie","t":"Imagerie","x":"Hémorragie intrakystique Kyste sous tension, douloureux au passage de la sonde, contenu échogène hétérogène proche de celui du kyste lutéal hémorragique. Fissure Kyste affaissé aux contours irréguliers, épanchement échogène de faible abondance dans le cul-de-sac de Douglas. Rupture Saignement d'un vaisseau de la paroi du kyste : hémopéritoine abondant qui remonte dans les gouttières et l'espace de Morison. Scanner : liquide de densité élevée ; caillot sentinelle plus dense au contact de l'ovaire qui saigne ; extravasation de contraste en cas de saignement actif."},{"i":"signes-cles","t":"Signes clés","x":"Caillot sentinelle = localisation de la source du saignement. Triade : kyste ovarien + hémopéritoine + βhCG négatifs."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Grossesse extra-utérine rompue : à éliminer en premier (βhCG). Torsion d'annexe, salpingite, appendicite."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Hémopéritoine modéré et patiente stable : surveillance médicale. Hémopéritoine abondant, instabilité hémodynamique ou extravasation active : chirurgie en urgence (ou embolisation selon le contexte)."},{"i":"pieges","t":"Pièges","x":"Un épanchement de faible abondance dans le Douglas peut être physiologique ; c'est son caractère échogène et son abondance qui orientent. Ne jamais conclure à une rupture de kyste avant d'avoir le résultat des βhCG."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Côté et aspect du kyste, abondance et extension de l'hémopéritoine (Douglas seul, gouttières, Morison), caillot sentinelle, saignement actif."}]},{"t":"Torsion d'annexe","n":"Torsion d'annexe","u":"ovaire/torsion-annexe.html","c":"Ovaire","b":"urgence chirurgicale dont le diagnostic repose sur la morphologie. Un flux Doppler conservéne l'élimine pas.","s":[{"i":"terrain","t":"Terrain","x":"Femme jeune, enfant, grossesse, stimulation ovarienne. Le plus souvent sur une masse annexielle homolatérale de plus de 5 cm, surtout dense : kyste dermoïde (tératome mature), fibrome ovarien. Aussi sur ovaires stimulés. Très rare sur un endométriome ou une masse maligne, que les adhérences fixent. Possible sur un ovaire normal, surtout chez l'enfant. Douleur pelvienne brutale et intense, nausées, vomissements ; parfois épisodes antérieurs de douleurs spontanément régressives (torsion puis détorsion)."},{"i":"mecanisme","t":"Mécanisme","x":"L'axe tubo-ovarien tourne sur lui-même et entraîne ses pédicules vasculaires, utéro-ovarien et lombo-ovarien. Phase précoce, réversible : les veines et les lymphatiques, à paroi souple, se ferment en premier. L'annexe se congestionne et s'œdématie, alors que le flux artériel persiste. Phase tardive, irréversible : l'occlusion artérielle entraîne une nécrose ischémique tubo-ovarienne. Cette séquence explique pourquoi un flux artériel au Doppler n'élimine pas une torsion."},{"i":"imagerie","t":"Imagerie","x":"Échographie (examen de première intention) Ovaire augmenté de volume, nettement plus gros que le controlatéral, stroma œdématié, follicules refoulés en périphérie. Médialisation de l'ovaire : en position médiane, dans le Douglas ou au-dessus de l'utérus. Tour de spire et épaississement du pédicule ovarien, en cible ou en tourbillon au Doppler. Épanchement libre. Scanner Ovaire augmenté, utérus dévié du côté de la torsion, trompe épaissie, infiltration de la graisse, ascite ; défaut de rehaussement si nécrose. IRM Stade réversible : ovaire augmenté de volume, œdème stromal en hypersignal T2, follicules refoulés en périphérie ; tour de spire du pédicule et dilatation du pédicule vasculaire en amont ; déviation de l'utérus du côté de la torsion. Hypersignal T1 du stroma ou de la paroi en saturation de graisse = infarcissement hémorragique. Absence de rehaussement = nécrose. Stade irréversible (nécrose établie) Clinique trompeuse : les douleurs s'atténuent progressivement. Masse mixte, solide et kystique, dont la portion solide ne se rehausse pas. Remaniements hémorragiques en hypersignal T1 en saturation de graisse : signe corrélé à la non-viabilité de l'annexe."},{"i":"signes-cles","t":"Signes clés","x":"Tour de spire du pédicule : signe le plus spécifique. Douleur aiguë + tératome ou gros kyste = torsion jusqu'à preuve du contraire."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Rupture ou hémorragie de kyste, grossesse extra-utérine, abcès tubo-ovarien, appendicite. Œdème ovarien massif : peut correspondre à une torsion partielle ou intermittente. Torsion tubaire isolée : ovaire normal, trompe dilatée et tordue. Lésion ovarienne kystique à paroi épaisse : trois causes à connaître Corps jaune et kyste lutéal hémorragique. Torsion d'annexe. Abcès tubo-ovarien."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Avis chirurgical urgent : cœlioscopie avec détorsion et conservation de l'ovaire autant que possible, même s'il paraît nécrosé."},{"i":"pieges","t":"Pièges","x":"Doppler normal : la double vascularisation (artères ovarienne et utérine) et la torsion intermittente gardent souvent un flux. Torsion sur ovaire normal chez l'enfant : pas de masse pour attirer l'attention. Ne pas chercher à caractériser une masse annexielle si la torsion est irréversible : la nécrose et les remaniements hémorragiques faussent l'analyse. Devant toute masse annexielle nécrotico-hémorragique, rechercher un épisode douloureux pelvien antérieur qui ferait évoquer une torsion."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et position de l'ovaire, tour de spire, flux Doppler, masse sous-jacente, épanchement, signes de nécrose en IRM ou au scanner."}]},{"t":"Syndrome des ovaires polykystiques","n":"SOPK","u":"ovaire/sopk.html","c":"Ovaire","b":"le SOPK est un diagnostic clinique, biologique et échographique. L'échographie n'apporte qu'un des trois critères : plus de 25 follicules par ovaire et des ovaires augmentés de surface ou de volume.","s":[{"i":"terrain","t":"Terrain","x":"Femme en âge de procréer ; trouble endocrinien fréquent. Troubles du cycle, hyperandrogénie (hirsutisme, acné), infertilité."},{"i":"criteres-diagnostiques","t":"Critères diagnostiques","x":"Au moins 2 critères sur 3, après exclusion des autres causes : Dysovulation ou anovulation. Hyperandrogénie clinique ou biologique. Ovaires polykystiques à l'échographie."},{"i":"ovaires-polykystiques-a-l-echographie-sopk","t":"Ovaires polykystiques à l'échographie (≠ SOPK)","x":"Deux critères échographiques réunis : Surface ovarienne > 5,5 cm² (ou somme des deux surfaces > 11 cm²), ou volume ovarien > 10 cm³. Comptage folliculaire > 25 par ovaire, follicules < 10 mm. Mesure en l'absence de corps jaune, comptage à J3 du cycle."},{"i":"imagerie","t":"Imagerie","x":"Échographie : augmentation de volume bilatérale des ovaires, follicules en répartition périphérique, hypertrophie du stroma ovarien. IRM (non indiquée pour le diagnostic) : follicules en hypersignal T2 en périphérie, stroma central en hyposignal T2."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Ovaires multifolliculaires de l'adolescente ou de l'hypogonadisme : follicules répartis dans tout l'ovaire, sans stroma abondant. Hyperthécose : hyperandrogénie plus marquée, stroma solide."},{"i":"pieges","t":"Pièges","x":"Pas d'échographie pour ce diagnostic dans les 8 ans qui suivent les premières règles : les ovaires multifolliculaires sont normaux à cet âge. Ne pas compter un corps jaune ou un follicule dominant parmi les follicules antraux. Une échographie évocatrice ne suffit pas : sans les critères cliniques ou biologiques, ce n'est pas un SOPK."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Voie d'abord, nombre de follicules par ovaire, volume des deux ovaires, absence de follicule dominant, de corps jaune ou de kyste au moment de la mesure."}]},{"t":"Lésions pseudotumorales de l'ovaire","n":"Lésions pseudotumorales","u":"ovaire/lesions-pseudotumorales.html","c":"Ovaire","b":"ces lésions non tumorales gardent l'architecture de l'ovaire, avec des follicules refoulés en périphérie. Le contexte (âge, hormones, chirurgie, torsion) fait le diagnostic.","s":[{"i":"dystrophie-macro-antrale","t":"Dystrophie macro-antrale","x":"Contexte inflammatoire pelvien : antécédent de chirurgie ou d'infection, endométriose, adhérences. Ovaire souvent unilatéral, augmenté de volume, contours polycycliques, macro-kystes à paroi fine (1,5 à 8 cm), pseudokystes péritonéaux associés. Diagnostic différentiel : tumeur multiloculaire (mucineuse, séreuse, granulosa). Une surveillance rapprochée tranche."},{"i":"lesions-stromales","t":"Lésions stromales","x":"Entité · Terrain · Imagerie · Point clé Œdème ovarien massif · Femme jeune, douleur pelvienne · Unilatéral dans 90 % des cas, ovaire augmenté, franc hypersignal T2 du stroma, follicules en périphérie, peu vascularisé · Unilatéral : chercher une torsion partielle ou intermittente. Bilatéral : chercher des métastases (gastriques surtout) Fibromatose ovarienne · Femme jeune, antécédent de torsion ou de chirurgie · Unilatérale dans 80 % des cas, plages fibreuses mal limitées autour des follicules, franc hyposignal T2, hyposignal diffusion, rehaussement faible · Stade évolué de l'œdème ; le fibrome est, lui, une masse bien limitée Hyperplasie stromale · Femme ménopausée · Bilatérale, épaississement stromal en hyposignal T2, sans hypersignal diffusion, rehaussement faible et progressif · Associée à une hyperandrogénie ou à un cancer de l'endomètre Hyperthécose · Surtout après la ménopause, plus rarement avant · Bilatérale, ovaires augmentés et arrondis, stroma solide en hyposignal T2, rehaussement faible · Hyperandrogénie marquée, parfois virilisation"},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Métastases solides bilatérales (sein lobulaire, estomac) : signal T2 intermédiaire, hypersignal diffusion, rehaussement plus franc (courbe de type 2). Tumeur sécrétante d'androgènes (Sertoli-Leydig, tumeur à cellules stéroïdes) : masse focale unilatérale."},{"i":"pieges","t":"Pièges","x":"Œdème ovarien massif et torsion se recouvrent : un gros ovaire œdématié et douloureux impose de chercher un tour de spire. L'hyperthécose et l'hyperplasie stromale se ressemblent beaucoup en imagerie ; seule l'histologie les distingue formellement."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Uni- ou bilatéralité, taille des ovaires, répartition des follicules, signal T2 et diffusion du stroma, signes de torsion, endomètre (épaissi ou non)."}]},{"t":"Hyperstimulation ovarienne","n":"Hyperstimulation ovarienne","u":"ovaire/hyperstimulation-ovarienne.html","c":"Ovaire","b":"deux gros ovaires multikystiques, symétriques, sans portion solide, dans un contexte de stimulation ou de grossesse. La gravité se juge sur l'ascite, l'épanchement pleural et la taille des ovaires.","s":[{"i":"terrain","t":"Terrain","x":"Exogène : après traitement inducteur de l'ovulation (procréation médicalement assistée). Endogène : grossesse avec hCG élevée (grossesse multiple, môle) ; on parle d'hyperreactio luteinalis ou de kystes lutéiniques."},{"i":"imagerie","t":"Imagerie","x":"Ovaires bilatéraux et symétriques, très augmentés de volume, multikystiques, loculi de taille similaire. Kystes à paroi fine, parfois hémorragiques, sans portion solide ni végétation. Ascite, épanchement pleural dans les formes graves."},{"i":"gravite-reperes-usuels","t":"Gravité (repères usuels)","x":"Forme · Taille des ovaires · Signes associés Légère · < 8 cm · Douleur et ballonnement modérés Modérée · 8 à 12 cm · Ascite visible en échographie Sévère · > 12 cm · Ascite clinique, épanchement pleural, troubles hydro-électrolytiques"},{"i":"complications","t":"Complications","x":"Torsion d'annexe, rupture ou hémorragie de kyste, thromboses veineuses et artérielles."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Tumeur ovarienne multiloculaire (mucineuse, séreuse, granulosa) : habituellement unilatérale, hors de ce contexte."},{"i":"pieges","t":"Pièges","x":"Ne pas proposer de chirurgie pour ces ovaires : ils régressent avec la baisse de l'hCG. Une douleur brutale sur des ovaires stimulés doit faire chercher une torsion."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille des deux ovaires, aspect des kystes, ascite (abondance), épanchement pleural, signes de torsion ou de thrombose."}]},{"t":"Démarche devant une masse annexielle","n":"Démarche devant une masse","u":"ovaire/demarche-masse-annexielle.html","c":"Ovaire","b":"l'échographie trie, l'IRM caractérise ce qui reste indéterminé, le scanner sert au bilan d'extension. La question centrale est l'existence d'une portion tissulaire et son comportement.","s":[{"i":"","t":"","x":"Sans portion tissulaire, ou avec un tissu en hyposignal T2 et en diffusion, la masse reste à faible risque ; sinon, c'est la courbe de rehaussement qui fixe le score."},{"i":"etape-1-la-masse-est-elle-ovarienne","t":"Étape 1 : la masse est-elle ovarienne ?","x":"Pour une origine ovarienne : croissant ovarien péri-lésionnel, pédicule ovarien qui mène à la masse, ovaire homolatéral non vu séparément. Origines à éliminer : myome sous-séreux pédiculé (vaisseaux qui le relient à l'utérus, signal du myomètre), trompe (hydrosalpinx, pyosalpinx), kyste para-ovarien, pseudokyste péritonéal, lésion digestive, adénopathie."},{"i":"etape-2-quel-est-le-contenu","t":"Étape 2 : quel est le contenu ?","x":"Contenu · Indice d'imagerie · Lésions évoquées Liquide pur · Anéchogène ; hypersignal T2, hyposignal T1 · Kyste folliculaire, cystadénome séreux, kyste para-ovarien Graisse · Hyperéchogène avec cône d'ombre ; hypersignal T1 qui chute en saturation de graisse · Tératome mature Sang · Contenu échogène finement piqueté ou en « filet de pêche » ; hypersignal T1 qui persiste en saturation de graisse · Endométriome (hypersignal T1 ≥ graisse, shading T2), kyste lutéal hémorragique (hypersignal T1 < graisse) Mucine · Loculi de signaux différents · Tumeur mucineuse Tissu · Composante qui se rehausse · Tumeur à caractériser"},{"i":"etape-3-analyser-la-portion-tissulaire","t":"Étape 3 : analyser la portion tissulaire","x":"Portion tissulaire = ce qui se rehausse : végétation, nodule mural, cloison irrégulière ou épaisse, masse solide. Débris, caillots et phanères ne se rehaussent pas. Paroi et cloisons fines et régulières qui se rehaussent ne comptent pas. En IRM : signal T2 et diffusion comparés au myomètre externe, puis courbe de rehaussement dynamique comparée au myomètre externe. Tissu en hyposignal T2 franc ET en hyposignal en diffusion haute valeur de b = bénin (fibrome, fibrothécome, Brenner, cystadénofibrome)."},{"i":"etape-4-chercher-les-signes-d-extension","t":"Étape 4 : chercher les signes d'extension","x":"Ascite (au-delà d'une lame physiologique du Douglas), carcinose péritonéale, adénopathies, lésions bilatérales. Masses bilatérales solides ou mucineuses : penser aux métastases et chercher un primitif (digestif, sein)."},{"i":"protocole-irm-d-une-masse-annexielle","t":"Protocole IRM d'une masse annexielle","x":"T2 dans au moins deux plans, avec un axial étendu jusqu'aux hiles rénaux. T1 sans et avec saturation de la graisse. Diffusion axiale avec une valeur de b ≥ 1000. T1 dynamique après injection (résolution temporelle ≤ 15 s), puis T1 tardif avec saturation de la graisse. Indications : masse pelvienne indéterminée ou complexe, masse > 7 cm, masse avec végétation, mixte ou solide."},{"i":"pieges","t":"Pièges","x":"La diffusion n'est pas interprétable dans une zone en hypersignal T1 (sang, graisse). Le croissant ovarien autour d'une lésion est un argument d'origine, pas de bénignité."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Origine de la masse, taille, contenu, portion tissulaire (taille, signal T2, diffusion, courbe), signes d'extension, score O-RADS."}]},{"t":"O-RADS échographie","n":"O-RADS échographie","u":"ovaire/o-rads-echographie.html","c":"Ovaire","b":"O-RADS échographie (version 2022) classe une masse annexielle de 0 à 5 selon sa morphologie, sa taille et sa vascularisation. Le score couleur (SC) va de 1 (pas de flux) à 4 (flux très abondant).","s":[{"i":"definitions","t":"Définitions","x":"Portion tissulaire : composante vascularisée ou rehaussée. Les débris, caillots et phanères n'en sont pas. Végétation (projection papillaire) : portion tissulaire d'au moins 3 mm de hauteur, née de la paroi ou d'une cloison, qui fait saillie dans le kyste. Paroi ou cloison irrégulière : irrégularité de moins de 3 mm de hauteur. Lésion solide : au moins 80 % de tissu. Ascite : en dehors d'une petite lame physiologique du cul-de-sac de Douglas, et sans autre cause."},{"i":"categories","t":"Catégories","x":"O-RADS · Risque de malignité · Critères principaux · Conduite 0 · Non évaluable · Examen techniquement incomplet · Nouvelle échographie ou IRM 1 · Ovaire normal · Follicule ou corps jaune ≤ 3 cm chez la femme non ménopausée · Aucune 2 · < 1 % · Kyste simple < 10 cm ; kyste uniloculaire non simple ou biloculaire à paroi lisse < 10 cm ; lésion bénigne typique < 10 cm (kyste hémorragique, kyste dermoïde, endométriome) ; kyste para-ovarien, pseudo-kyste péritonéal, hydrosalpinx typiques · Suivi selon la taille et le statut ménopausique 3 · 1 à < 10 % · Kyste uni- ou biloculaire lisse ≥ 10 cm ; lésion bénigne typique ≥ 10 cm ; kyste uniloculaire irrégulier ; kyste multiloculaire lisse < 10 cm, SC < 4; lésion solide lisse SC 1 ; lésion solide lisse avec atténuation postérieure, SC 2–3 · Avis gynécologique ; échographiste référent ou IRM 4 · 10 à < 50 % · Kyste uniloculaire avec 1 à 3 végétations ou une portion tissulaire ; kyste bi- ou multiloculaire avec portion tissulaire, SC 1–2 ; kyste multiloculaire sans portion tissulaire ≥ 10 cm, ou SC 4, ou à paroi ou cloisons irrégulières ; kyste biloculaire irrégulier ; lésion solide lisse sans atténuation postérieure, SC 2–3 · IRM ou échographiste référent ; gynécologue avec avis oncologique 5 · ≥ 50 % · Kyste uniloculaire avec ≥ 4 végétations ; kyste bi- ou multiloculaire avec portion tissulaire, SC 3–4 ; lésion solide lisse SC 4 ; lésion solide à contours irréguliers ; ascite et/ou nodules péritonéaux · Gynécologue oncologue"},{"i":"lesions-benignes-typiques-o-rads-2","t":"Lésions bénignes typiques (O-RADS 2)","x":"Lésion · Aspect typique · Suivi Kyste hémorragique · Uniloculaire, contenu en « filet de pêche » ou caillot, sans flux interne · Non ménopausée ≤ 5 cm : aucun ; > 5 cm : contrôle à 2–3 mois ; ménopausée : contrôle à 2–3 mois ou IRM Kyste dermoïde · ≤ 3 loculi, sans flux, zone hyperéchogène avec atténuation postérieure, lignes et points hyperéchogènes, sphères flottantes · Contrôle à 12 mois s'il n'est pas opéré Endométriome · ≤ 3 loculi, sans flux, contenu échogène homogène finement piqueté, ± petits foyers échogènes pariétaux · Non ménopausée : contrôle à 12 mois s'il n'est pas opéré ; ménopausée : contrôle à 2–3 mois ou IRM Kyste para-ovarien · Kyste simple séparé de l'ovaire · Aucun Pseudo-kyste péritonéal · Collection qui épouse les organes, ovaire en bordure ou suspendu, ± cloisons · Aucun en imagerie Hydrosalpinx · Structure tubulaire anéchogène, cloisons incomplètes, plis muqueux · Aucun en imagerie"},{"i":"pieges","t":"Pièges","x":"Le score s'applique aux patientes à risque moyen et sans symptôme aigu. Un caillot ou des phanères ne sont pas une portion tissulaire : vérifier l'absence de flux."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, nombre de loculi, contours, portion tissulaire et végétations (nombre), score couleur, ascite, catégorie O-RADS et conduite proposée."}]},{"t":"O-RADS IRM","n":"O-RADS IRM","u":"ovaire/o-rads-irm.html","c":"Ovaire","b":"le score O-RADS IRM classe en 5 catégories de risque les masses annexielles complexes ou indéterminées en échographie. Tout repose sur la portion tissulaire et sa courbe de rehaussement, comparée au myomètre externe.","s":[{"i":"protocole","t":"Protocole","x":"T2 dans deux plans au moins, axial jusqu'aux hiles rénaux. T1 sans et avec saturation de la graisse. Diffusion axiale, b ≥ 1000. T1 dynamique après injection (résolution temporelle ≤ 15 s), puis T1 tardif avec saturation de la graisse."},{"i":"definitions","t":"Définitions","x":"Portion tissulaire : toujours rehaussée ; végétation, nodule mural, cloison irrégulière ou lésion purement solide. Portion tissulaire en hyposignal T2 franc ET en hyposignal diffusion : en faveur de la bénignité (score 2), sans analyse de la courbe."},{"i":"courbes-de-rehaussement-par-rapport-au-myometre-externe","t":"Courbes de rehaussement (par rapport au myomètre externe)","x":"Courbe · Forme · Risque Type 1 · Montée progressive, sans épaulement · Faible Type 2 · Montée initiale moins rapide que le myomètre, puis plateau · Intermédiaire Type 3 · Montée initiale plus rapide que le myomètre · Élevé Sans séquence dynamique : rehaussement de la portion tissulaire ≤ myomètre à 30–40 s = score 4 ; > myomètre = score 5."},{"i":"scores","t":"Scores","x":"Score · Valeur prédictive positive · Critères 0 · Non évaluable · Examen incomplet 1 · Ovaire normal · Pas de lésion ; follicule, kyste hémorragique ou corps jaune ≤ 3 cm chez la femme non ménopausée 2 · < 0,5 % · Kyste uniloculaire sans rehaussement pariétal ; kyste uniloculaire à contenu liquidien pur ou endométriosique, paroi lisse rehaussée ; lésion graisseuse sans portion tissulaire ; portion tissulaire en hyposignal T2 franc et en hyposignal diffusion ; trompe dilatée à contenu liquidien pur et paroi fine ; kyste para-ovarien 3 · ≈ 5 % · Kyste uniloculaire à contenu protéique, hémorragique ou mucineux, paroi lisse rehaussée ; kyste multiloculaire sans graisse, cloisons et paroi lisses, sans portion tissulaire ; portion tissulaire avec courbe de type 1 ; trompe dilatée à contenu non liquidien pur ou à paroi épaisse et lisse 4 · ≈ 50 % · Portion tissulaire avec courbe de type 2 ; lésion graisseuse avec une portion tissulaire volumineuse 5 · ≈ 90 % · Portion tissulaire avec courbe de type 3 ; nodules ou épaississement irrégulier du péritoine, du mésentère ou de l'épiploon, avec ou sans ascite"},{"i":"pieges","t":"Pièges","x":"La protubérance de Rokitansky d'un kyste dermoïde peut se rehausser un peu sans faire passer en score 4 : il faut une portion tissulaire volumineuse. La diffusion n'est pas interprétable dans une zone en hypersignal T1. Une courbe de type 3 n'est pas toujours maligne : goitre ovarien, tumeur stromale sclérosante."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Origine, taille, contenu (signal T1, T1 FS, T2), portion tissulaire (taille, signal T2, diffusion, type de courbe), péritoine, score O-RADS IRM."}]},{"t":"Tumeurs épithéliales séreuses","n":"Tumeurs séreuses","u":"ovaire/tumeurs-epitheliales-sereuses.html","c":"Ovaire","b":"les végétations signent une tumeur épithéliale, pas la malignité. C'est leur nombre, leur taille, leur siège et leur comportement en IRM qui séparent bénin, frontière et malin.","s":[{"i":"terrain","t":"Terrain","x":"Tumeurs épithéliales les plus fréquentes, environ 30 % des tumeurs ovariennes ; à tout âge. Environ 70 % bénignes, 5 à 10 % frontières, 20 à 25 % malignes."},{"i":"imagerie","t":"Imagerie","x":"Forme · Aspect · Portion tissulaire Cystadénome séreux bénin · Kyste uniloculaire, rond, liquidien pur, paroi fine non vascularisée ; bilatéral dans 7 à 20 % des cas ; calcosphérites possibles · Aucune Cystadénome séreux bénin papillaire · Masse à prédominance kystique · Végétations peu nombreuses, endokystiques, < 1 cm, non vascularisées au Doppler ; hyposignal T2, hyposignal diffusion, courbe de type 1 Cystadénome séreux frontière · Masse à prédominance kystique, unilatérale (66 %), uni- ou multiloculaire · Végétations nombreuses, confluentes, > 1 cm, endo- et/ou exokystiques, flux central au Doppler ; signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 ; implants péritonéaux et ganglionnaires possibles Cystadénocarcinome séreux · Masse mixte ou à prédominance kystique, bilatérale (66 %) · Portions tissulaires irrégulières et végétations vascularisées ; T2 intermédiaire, hypersignal diffusion, courbe de type 2 ou 3 ; carcinose péritonéale, adénopathies"},{"i":"signes-cles","t":"Signes clés","x":"Végétation exokystique = tumeur frontière jusqu'à preuve du contraire. Calcifications de la tumeur, des ganglions ou de la carcinose : plutôt cystadénocarcinome de bas grade. Le cystadénocarcinome séreux est le plus fréquent des carcinomes ovariens (60 %), de haut grade dans 95 % des cas et découvert à un stade avancé dans 80 % des cas."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kyste folliculaire (≥ 3 cm, femme non ménopausée) : régresse en 6 à 12 semaines ; aucun critère d'imagerie ne le distingue d'un cystadénome séreux. Kyste d'inclusion corticale : femme ménopausée, < 1 cm. Lésions extra-ovariennes (kyste para-ovarien, hydrosalpinx) : pas de croissant ovarien. Lésions mixtes bilatérales : éliminer des métastases ovariennes et chercher un cancer primitif (digestif, sein)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Kyste liquidien pur : femme non ménopausée, kyste fonctionnel entre 3 et 5 cm (contrôle optionnel à 6–12 semaines) ; femme ménopausée, lésion organique au-delà de 1 cm ; IRM si > 7 cm. Végétations ou portion tissulaire : IRM avec score O-RADS IRM, puis avis gynécologique ou oncologique. Suspicion de carcinome : scanner thoraco-abdomino-pelvien pour la cartographie de la carcinose."},{"i":"pieges","t":"Pièges","x":"Des végétations en hyposignal T2 et hyposignal diffusion avec une courbe de type 1 sont en faveur d'un cystadénome papillaire bénin. Le cystadénome séreux frontière peut donner des implants péritonéaux : ce n'est pas forcément un carcinome."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Latéralité, taille, nombre de loculi, végétations (nombre, taille, siège endo- ou exokystique, signal, courbe), ascite, carcinose, adénopathies."}]},{"t":"Tumeurs épithéliales mucineuses","n":"Tumeurs mucineuses","u":"ovaire/tumeurs-epitheliales-mucineuses.html","c":"Ovaire","b":"volumineuse masse multiloculaire, unilatérale, aux loculi de signaux différents. Une tumeur mucineuse bilatérale est une métastase d'origine digestive jusqu'à preuve du contraire.","s":[{"i":"terrain","t":"Terrain","x":"10 à 15 % des tumeurs ovariennes, femme de 20 à 50 ans. Continuum lésionnel : environ 80 % bénignes, 16 à 17 % frontières, moins de 5 % malignes."},{"i":"imagerie","t":"Imagerie","x":"Masse à prédominance kystique, volumineuse (10 à 15 cm), unilatérale (95 %). Multiloculaire, avec des loculi de signaux différents en T1 et en T2 (mucine plus ou moins concentrée). Forme · Cloisons et portion tissulaire Tumeur mucineuse bénigne · Cloisons fines, peu nombreuses, régulières Tumeur mucineuse frontière · Cloisons irrégulières, nombreuses, regroupées ; microvégétations en hyposignal T2, < 3 mm Tumeur mucineuse invasive · Cloisons irrégulières et épaisses et/ou nodule tissulaire en signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 (plus rarement de type 3)"},{"i":"signes-cles","t":"Signes clés","x":"Le regroupement des cloisons et les microvégétations orientent vers une tumeur frontière. Tumeur mucineuse + épanchement intra-abdominal : suspecter une rupture et un pseudomyxome péritonéal."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Métastases ovariennes d'un cancer digestif (côlon, appendice, estomac, pancréas) : bilatérales. Dystrophie macro-antrale, tumeur de la granulosa, tumeur séreuse multiloculaire. Associations lésionnelles possibles sur le même ovaire : tumeur de Brenner, kyste dermoïde."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"IRM avec score O-RADS IRM ; chirurgie, avec avis oncologique en cas de cloisons irrégulières ou de nodule. Bilatéralité ou pseudomyxome : chercher un cancer digestif, en premier lieu appendiculaire."},{"i":"pieges","t":"Pièges","x":"Ne pas conclure à une tumeur mucineuse primitive devant des lésions bilatérales. La taille de la masse ne préjuge pas de sa malignité : seules les cloisons et la portion tissulaire comptent."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, latéralité, nombre et signal des loculi, épaisseur et regroupement des cloisons, microvégétations ou nodule (signal, diffusion, courbe), épanchement, appendice."}]},{"t":"Cystadénofibrome et tumeur de Brenner","n":"Cystadénofibrome et Brenner","u":"ovaire/cystadenofibrome-brenner.html","c":"Ovaire","b":"deux tumeurs épithéliales bénignes dont la portion tissulaire fibreuse est en hyposignal T2 franc et en hyposignal diffusion. Elles ne doivent pas être prises pour des cancers.","s":[{"i":"cystadenofibrome","t":"Cystadénofibrome","x":"Définition : tumeur séreuse bénigne avec une portion fibromateuse prédominante (cystadénofibrome) ou quasi exclusive (adénofibrome). Masse à prédominance kystique, plus rarement solide ; bilatérale plus souvent qu'unilatérale ; multiloculaire plus souvent qu'uniloculaire. Portion tissulaire : cloisons épaisses souvent irrégulières, végétations, nodule mural (56 %). Portion tissulaire en hyposignal T2 franc et hyposignal diffusion, courbe de type 1 (rarement de type 2) : score O-RADS IRM 2. Diagnostic différentiel : cystadénome séreux associé à un fibrome ovarien."},{"i":"tumeur-de-brenner","t":"Tumeur de Brenner","x":"Définition : tumeur épithéliale à cellules transitionnelles (différenciation urothéliale). Rare (1 à 2 % des tumeurs ovariennes), bénigne dans 95 % des cas. Unilatérale (94 %), bien limitée, petite (souvent ≤ 2 cm), solide pure. Échographie : isoéchogène au myomètre, atténuation postérieure, faible vascularisation centrale. IRM : hyposignal T2 franc, diffusion variable, courbe de type 2. Calcifications centrales punctiformes dans 50 % des cas. Associations lésionnelles : kyste dermoïde, tumeur mucineuse."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Fibrome ovarien : courbe de type 1. Myome sous-séreux pédiculé : extra-ovarien, raccordé au myomètre, encorbellement vasculaire au Doppler, souvent d'autres myomes."},{"i":"pieges","t":"Pièges","x":"Une portion tissulaire épaisse et irrégulière inquiète en échographie : l'IRM la reclasse si elle est en hyposignal T2 franc et en hyposignal diffusion. Une tumeur de Brenner peut accompagner une tumeur mucineuse : analyser séparément chaque composante."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Signal T2 et diffusion de la portion tissulaire, type de courbe, calcifications, lésion associée, score O-RADS IRM."}]},{"t":"Carcinomes endométrioïde et à cellules claires","n":"Endométrioïde et cellules claires","u":"ovaire/endometrioide-cellules-claires.html","c":"Ovaire","b":"ces carcinomes naissent souvent sur une endométriose. Une portion tissulaire vascularisée dans un endométriome doit faire évoquer une transformation maligne.","s":[{"i":"terrain","t":"Terrain","x":"Association à l'endométriose : 40 % pour le carcinome endométrioïde, 70 % pour le carcinome à cellules claires. Femme plus jeune que pour les autres tumeurs épithéliales malignes, endométriose souvent connue. Carcinome endométrioïde ovarien associé à un cancer de l'endomètre dans 20 % des cas."},{"i":"imagerie","t":"Imagerie","x":"Masse mixte, unilatérale plus souvent que bilatérale, parfois développée sur un endométriome. Endométriose pelvienne associée fréquente. Portions tissulaires en signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 ou 3. Remaniements hémorragiques plus fréquents dans le carcinome endométrioïde."},{"i":"transformation-maligne-d-un-endometriome","t":"Transformation maligne d'un endométriome","x":"Critères de suspicion Taille > 10 cm. Asymétrie de taille par rapport aux autres endométriomes. Apparition d'une portion tissulaire. Imagerie Échographie : végétations ou nodules solides vascularisés au Doppler. IRM : portion tissulaire en hyposignal T1, signal T2 variable, hypersignal diffusion ; les images de soustraction aident à voir le rehaussement dans un kyste en hypersignal T1. Végétation + courbe de type 2 → tumeur frontière ; nodule solide + courbe de type 2 ou 3 → tumeur invasive."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Endométriome décidualisé pendant la grossesse : portion tissulaire vascularisée en hypersignal T2 franc, sans progression pendant la grossesse, disparition après l'accouchement. Caillot dans un endométriome : non rehaussé."},{"i":"signes-cles","t":"Signes clés","x":"Tumeur ovarienne + anomalies utérines (endomètre épaissi, adénomyose) : penser à des tumeurs endométrioïdes synchrones de l'ovaire et de l'utérus, ou à une tumeur ovarienne sécrétante (granulosa). Devant des tumeurs endométrioïdes de l'ovaire et de l'utérus : tumeurs synchrones, primitif utérin avec métastases ovariennes, ou primitif ovarien avec métastases utérines."},{"i":"pieges","t":"Pièges","x":"Aucun critère IRM ne distingue un carcinome endométrioïde d'un carcinome à cellules claires. La diffusion n'est pas interprétable dans un contenu en hypersignal T1 : juger le rehaussement sur les soustractions."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et évolution de l'endométriome, portion tissulaire (taille, signal, diffusion, courbe), endomètre, autres localisations d'endométriose, score O-RADS IRM."}]},{"t":"Tératome mature","n":"Tératome mature","u":"ovaire/teratome-mature.html","c":"Ovaire","b":"la graisse est pathognomonique du tératome. Douleur pelvienne aiguë + kyste dermoïde = torsion d'annexe jusqu'à preuve du contraire.","s":[{"i":"terrain","t":"Terrain","x":"Tumeur germinale la plus fréquente (95 % des tumeurs germinales), 20 % des tumeurs ovariennes. À tout âge, avec une prédominance chez la femme jeune."},{"i":"imagerie","t":"Imagerie","x":"Kystique ou mixte, rond, uniloculaire (88 %), unilatéral plus souvent que bilatéral (12 %), hétérogène. Composantes : protubérance de Rokitansky, graisse, calcifications et dents, phanères (portions hyperéchogènes). Protubérance de Rokitansky Hyperéchogène avec atténuation postérieure marquée. Taille < 4 cm, ronde, angles de raccordement aigus avec la paroi. Graisse Échographie : échogénicité variable, de hypo- (sébum pur) à hyperéchogène (sébum + phanères), niveau liquidien possible, atténuation postérieure variable. IRM : hypersignal T1 ≥ graisse, qui chute en T1 FS. Scanner : densité graisseuse négative."},{"i":"complications","t":"Complications","x":"Torsion d'annexe (3 à 16 %). Rupture (1 à 4 %) : péritonite chimique granulomateuse avec implants péritonéaux. Transformation maligne (0,2 à 4 %) : protubérance de Rokitansky irrégulière, > 5 cm, à angles de raccordement obtus, épaississement pariétal localisé. Surinfection (exceptionnelle). Auto-immunité : anémie hémolytique, encéphalite à anticorps anti-NMDA."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kystes à contenu échogène : kyste lutéal hémorragique, endométriome (hypersignal T1 qui persiste en FS), abcès tubo-ovarien. Tératome immature : portion tissulaire prédominante, graisse en petites plages, nombreuses calcifications fines."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Prise en charge chirurgicale le plus souvent au-delà de 4 cm, du fait du risque de torsion. S'il n'est pas opéré : contrôle échographique à 12 mois (O-RADS 2 si < 10 cm)."},{"i":"pieges","t":"Pièges","x":"Une protubérance de Rokitansky peu rehaussée ne fait pas passer en O-RADS IRM 4 ; il faut une portion tissulaire volumineuse. Un petit kyste dermoïde très hyperéchogène peut se confondre avec le gaz digestif (« pointe de l'iceberg »)."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, bilatéralité, signes de complication (torsion, transformation maligne, rupture), parenchyme ovarien sain restant (fertilité ultérieure)."}]},{"t":"Tératome immature et goitre ovarien","n":"Tératome immature et goitre ovarien","u":"ovaire/teratome-immature-goitre-ovarien.html","c":"Ovaire","b":"deux tératomes rares. Le tératome immature est malin et à prédominance tissulaire chez la jeune fille ; le goitre ovarien est bénin, reconnaissable à son contenu colloïde.","s":[{"i":"teratome-immature","t":"Tératome immature","x":"Définition : tératome malin fait de dérivés immatures des trois feuillets embryonnaires. Terrain : jeune fille de moins de 20 ans ; 1 % des tumeurs ovariennes, 3 % des tumeurs germinales. Volumineux (> 10 cm), hétérogène, mixte, à prédominance solide ou kystique. Portion tissulaire microkystique en signal T2 intermédiaire, rehaussement tardif (courbe de type 2 ou 3, non discriminante). Graisse en fines plages (< 1 cm), calcifications nombreuses et fines. Kyste dermoïde associé sur le même ovaire (26 %) ou l'ovaire controlatéral (10 %). Rupture : implants péritonéaux graisseux et/ou calcifiés, gliomatose péritonéale secondaire."},{"i":"goitre-ovarien","t":"Goitre ovarien","x":"Définition : tératome monodermique bénin, à composante thyroïdienne prédominante ou quasi exclusive. Rare : 2 % des tumeurs germinales. Masse à prédominance kystique ou mixte, multiloculaire, loculi de signaux différents. Contenu colloïde, pathognomonique : iso- ou hypersignal T1, hyposignal T2 franc, pas de rehaussement. Cloisons épaisses et/ou nodule tissulaire : signal T2 intermédiaire, hypersignal diffusion, courbe de type 3 (tissu thyroïdien). Kyste dermoïde associé fréquent."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kyste dermoïde : graisse abondante, protubérance de Rokitansky < 4 cm, peu de portion tissulaire. Tumeur mucineuse : loculi de signaux différents, sans contenu colloïde en hyposignal T2 franc."},{"i":"pieges","t":"Pièges","x":"Le goitre ovarien a une courbe de type 3 alors qu'il est bénin. Une masse surtout tissulaire avec quelques petites plages de graisse chez une jeune fille ne doit pas être prise pour un kyste dermoïde."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, proportion de portion tissulaire, graisse (abondance, répartition), calcifications, loculi colloïdes, implants péritonéaux."}]},{"t":"Tumeurs germinales malignes non tératomateuses","n":"Germinales malignes","u":"ovaire/germinales-malignes.html","c":"Ovaire","b":"masse ovarienne complexe + jeune fille ou adolescente + élévation des marqueurs = tumeur germinale non tératomateuse. L'imagerie est peu spécifique, le contexte clinico-biologique oriente.","s":[{"i":"terrain","t":"Terrain","x":"Rares, malignes, chez la femme jeune. 60 % des tumeurs ovariennes de la jeune fille sont des tumeurs germinales (tous types confondus)."},{"i":"imagerie","t":"Imagerie","x":"Unilatérales, volumineuses, mixtes ou solides. Hétérogènes : cloisons ou travées hypervascularisées, remaniements nécrotico-hémorragiques possibles."},{"i":"marqueurs-et-types","t":"Marqueurs et types","x":"Tumeur · Marqueur · Particularités Dysgerminome · LDH · La plus fréquente ; femme de 20 à 30 ans ; solide pure, signal T2 intermédiaire, volumineuse (> 10 cm), contours polylobés, cloisons internes hypervascularisées Tumeur du sac vitellin · αFP · Masse mixte, hétérogène Carcinome embryonnaire · αFP ou hCG · Masse mixte peu spécifique Choriocarcinome non gestationnel · hCG · Remaniements hémorragiques"},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Tératome immature : graisse en petites plages et calcifications fines. Tumeur de la granulosa juvénile : signes d'hyperœstrogénie (pseudopuberté précoce). Lymphome : masse solide homogène, souvent bilatérale, adénopathies."},{"i":"pieges","t":"Pièges","x":"Toujours doser les marqueurs (αFP, hCG, LDH) devant une masse ovarienne solide de l'adolescente. Une hCG élevée oriente aussi vers une grossesse : l'éliminer d'abord."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, composantes solide et kystique, cloisons vascularisées, nécrose ou hémorragie, ascite, adénopathies, carcinose."}]},{"t":"Fibrome et fibrothécome","n":"Fibrome et fibrothécome","u":"ovaire/fibrome-fibrothecome.html","c":"Ovaire","b":"masse solide pure, bien limitée, en hyposignal T2 franc et hyposignal diffusion, avec une courbe de type 1 : c'est un fibrome, bénin.","s":[{"i":"terrain","t":"Terrain","x":"Tumeur des cordons sexuels et du stroma la plus fréquente (50 %), en périménopause. Le thécome peut sécréter des œstrogènes : endomètre épaissi, métrorragies."},{"i":"imagerie","t":"Imagerie","x":"Masse solide pure, unilatérale (90 %), ronde ou ovale, bien limitée, contours lobulés, parfois exophytique. Échographie : aspect variable, souvent hypoéchogène avec atténuation postérieure. IRM : hyposignal T2 franc, hyposignal diffusion, courbe de type 1. Lame d'épanchement péritonéal fréquente (50 à 70 %)."},{"i":"remaniements-possibles","t":"Remaniements possibles","x":"Remaniement · Signal Œdémateux · T2 intermédiaire, courbe de type 1 Kystique · Hypersignal T2, hyposignal T1 Hémorragique · T2 variable, hypersignal T1 Calcifié · Hyposignal T2 et T1 Myxoïde · Hypersignal T2, hyposignal T1, rehaussement Fibrome cellulaire · T2 intermédiaire, courbe de type 2 (ou 3) ; risque de récidive après exérèse"},{"i":"complications","t":"Complications","x":"Torsion d'annexe. Syndrome de Demons-Meigs : ascite + épanchement pleural qui régressent après exérèse."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Myome sous-séreux pédiculé : raccordé au myomètre, encorbellement vasculaire, autres myomes. Tumeur de Brenner : petite, calcifications centrales, courbe de type 2. Fibromatose ovarienne : plages mal limitées autour des follicules, pas de masse. Masses solides bilatérales : courbe de type 1 → fibromes bilatéraux (10 %) ; courbe de type 2 → métastases (sein, estomac, endomètre, lymphome)."},{"i":"pieges","t":"Pièges","x":"Un fibrome remanié ou cellulaire perd son hyposignal T2 franc : la courbe aide. Ascite + épanchement pleural + masse ovarienne ne signent pas toujours un cancer : penser au syndrome de Demons-Meigs. Fibromes bilatéraux et calcifiés chez une femme jeune : penser au syndrome de Gorlin."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, latéralité, signal T2, diffusion, type de courbe, remaniements, épanchement, endomètre (si thécome suspecté), score O-RADS IRM."}]},{"t":"Tumeurs des cordons sexuels","n":"Cordons sexuels","u":"ovaire/cordons-sexuels.html","c":"Ovaire","b":"devant une lésion ovarienne à prédominance solide, chercher les signes d'hypersécrétion. L'imprégnation œstrogénique oriente vers la granulosa ou le thécome, la virilisation vers la tumeur de Sertoli-Leydig.","s":[{"i":"terrain","t":"Terrain","x":"Troisième groupe de tumeurs ovariennes primitives (environ 8 %), souvent sécrétantes. Masses mixtes ou solides pures, polymorphes."},{"i":"signes-d-hypersecretion","t":"Signes d'hypersécrétion","x":"Imprégnation œstrogénique · Hyperandrogénie (virilisation) Pseudopuberté précoce, métrorragies, épaississement endométrial, adénomyose interne · Hypertrophie clitoridienne, aménorrhée ou spanioménorrhée, hirsutisme, acné, atrophie mammaire, raucité de la voix Tumeur de la granulosa, thécome · Tumeur de Sertoli-Leydig, tumeur à cellules stéroïdes"},{"i":"tumeurs","t":"Tumeurs","x":"Tumeur · Terrain et biologie · Imagerie Tumeur de la granulosa, forme adulte (95 %) · Périménopause ; métrorragies post-ménopausiques ; sécrétion d'œstrogènes (80 %), inhibine B · Solide, mixte ou à prédominance kystique, unilatérale, environ 10 cm, composante hémorragique, courbe de type 2 ou 3, hypertrophie du pédicule lombo-ovarien homolatéral Tumeur de la granulosa, forme juvénile (5 %) · Avant la puberté et avant 30 ans ; pseudopuberté précoce · Même aspect Tumeur de Sertoli-Leydig · Femme < 30 ans (75 %) ; virilisation ; testostérone et Δ4-androstènedione élevées si sécrétante (30 %) · Solide, mixte ou kystique, unilatérale (95 %), < 10 cm, ronde, bien limitée, portion solide en signal T2 intermédiaire, courbe de type 2 (ou 3) Tumeur stromale sclérosante · Bénigne, femme < 30 ans (82 %) · Solide ou mixte, unilatérale, < 10 cm, bien limitée, capsule en hyposignal T2, hypervascularisation périphérique annulaire au Doppler, rehaussement annulaire centripète (courbe de type 3) Tumeur à cellules stéroïdes · Rare ; androgènes surtout · Masse solide, peu spécifique"},{"i":"complications","t":"Complications","x":"Tumeur de la granulosa : rupture avec hémopéritoine."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Fibrome et fibrothécome : hyposignal T2 franc, courbe de type 1. Métastases solides : bilatérales, contexte de cancer connu. Hyperthécose et hyperplasie stromale : bilatérales, sans masse focale."},{"i":"pieges","t":"Pièges","x":"Une courbe de type 3 n'est pas toujours maligne : tumeur stromale sclérosante. Toujours regarder l'endomètre et le myomètre devant une masse ovarienne solide : leur épaississement trahit une sécrétion d'œstrogènes."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, composantes solide et kystique, hémorragie, signal T2, diffusion, courbe, pédicule ovarien, endomètre, hémopéritoine."}]},{"t":"Métastases ovariennes","n":"Métastases","u":"ovaire/metastases.html","c":"Ovaire","b":"des lésions ovariennes bilatérales, solides ou mixtes, doivent faire évoquer des métastases et chercher un cancer primitif, digestif ou mammaire.","s":[{"i":"terrain","t":"Terrain","x":"Environ 5 % des tumeurs ovariennes ; contexte oncologique connu dans deux tiers des cas. Dissémination hématogène, lymphatique ou péritonéale."},{"i":"imagerie","t":"Imagerie","x":"Bilatérales (60 à 80 %), parfois multifocales. Intra-ovariennes ou en implants de surface ; parenchyme ovarien sain adjacent parfois préservé. Œdème ovarien possible (infiltration lymphatique). Forme · Primitifs principaux · Aspect À prédominance solide · Sein, estomac, endomètre, lymphome · Signal T2 intermédiaire, hypersignal diffusion, courbe de type 2 À prédominance kystique · Côlon, sein, appendice, col, endomètre · Kystique multiloculaire ou mixte, courbe de type 2 La tumeur de Krukenberg désigne une métastase ovarienne à cellules en bague à chaton, le plus souvent d'origine gastrique."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Cystadénocarcinome séreux bilatéral : carcinose fréquente, pas de primitif extra-ovarien. Tumeur mucineuse primitive : unilatérale dans 95 % des cas. Fibromes bilatéraux : hyposignal T2 franc, hyposignal diffusion, courbe de type 1. Hyperplasie stromale : épaississement cortical bilatéral en hyposignal T2, sans hypersignal diffusion."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Scanner thoraco-abdomino-pelvien, endoscopies digestives, examen et imagerie des seins selon le contexte."},{"i":"pieges","t":"Pièges","x":"Une tumeur mucineuse bilatérale est une métastase d'origine digestive jusqu'à preuve du contraire. Œdème ovarien massif bilatéral : penser à une infiltration métastatique, surtout gastrique."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Bilatéralité, taille, composantes solide et kystique, signal T2, diffusion, courbe, carcinose, adénopathies, recherche d'un primitif."}]},{"t":"Endométriose : généralités et stratégie diagnostique","n":"Généralités et stratégie diagnostique","u":"endometriose/generalites-strategie.html","c":"Endométriose","b":"l'endométriose se cherche devant des douleurs pelviennes chroniques ou une infertilité. L'échographie endovaginale est l'examen de première intention, l'IRM pelvienne celui de deuxième intention.","s":[{"i":"definition","t":"Définition","x":"Présence de tissu endométrial fonctionnel en dehors de la cavité utérine. Fréquente : 5 à 20 % des femmes en âge de procréer ; physiopathologie multifactorielle, encore mal comprise."},{"i":"clinique","t":"Clinique","x":"Douleurs pelviennes chroniques (plus de 6 mois) : dysménorrhées intenses (EVA > 7, absentéisme, résistance aux antalgiques de palier 1) ; signes de localisation d'endométriose profonde : dyspareunies profondes positionnelles, recrudescence cataméniale des douleurs à la défécation ou des signes fonctionnels urinaires. Infertilité."},{"i":"formes","t":"Formes","x":"Forme · Lésions Endométriose superficielle · Implants et adhérences péritonéaux Endométriose ovarienne · Endométriome ovarien Endométriose profonde · Tissu fibro-musculaire sous-péritonéal"},{"i":"localisations","t":"Localisations","x":"Pelviennes : ovaires ; péritoine pelvien (adhérences, implants superficiels, collections) ; endométriose profonde sous-péritonéale postérieure (torus, ligaments utéro-sacrés, vagin, cloison recto-vaginale, paroi du recto-sigmoïde), latérale (paramètres, parois pelviennes, uretère, lame sacro-recto-génito-pubienne) et antérieure (vessie, ligament rond, cul-de-sac vésico-utérin) ; trompes (implants intratubaires, hématosalpinx). Extra-pelviennes : appendice, cæcum, iléon terminal, côlon et grêle, peau (cicatrice, paroi), diaphragme, plus rarement thorax, système nerveux, ganglions."},{"i":"strategie-diagnostique","t":"Stratégie diagnostique","x":"Première intention : échographie endovaginale. Deuxième intention : IRM pelvienne avec préparation digestive. Protocole IRM Préparation : jeûne de quelques heures, antipéristaltique, vessie modérément remplie, préparation digestive (lavement) ; opacification vaginale et/ou rectale par gel selon les équipes. T2 2D dans les plans sagittal, axial et coronal, complétés par un plan axial oblique perpendiculaire au grand axe du col : c'est le plan qui dégage le mieux le torus et les ligaments utéro-sacrés. Une séquence T2 3D avec reconstructions multiplanaires peut remplacer une partie des plans 2D. T1 sans et avec saturation de la graisse (par exemple T1 3D Dixon) : implants et spots hémorragiques en hypersignal T1. Séquence T2 rapide sur les reins : recherche d'une urétéro-hydronéphrose. Injection de gadolinium non systématique : elle est indiquée s'il existe une portion tissulaire dans une lésion annexielle (caillot ou tissu, transformation maligne) ; on réalise alors le protocole complet de masse annexielle, avec diffusion et séquence dynamique."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Traitement seulement si l'endométriose est symptomatique. Traitement médical en première intention (hormonothérapie) ; chirurgie en cas d'échec, en centre expert."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Endométriomes (nombre, taille, latéralité), localisations profondes par compartiment, atteinte digestive détaillée, retentissement urinaire (cavités rénales), adénomyose associée."}]},{"t":"Endométriome ovarien","n":"Endométriome ovarien","u":"endometriose/endometriome-ovarien.html","c":"Endométriose","b":"kyste à contenu échogène en fin piqueté homogène, en hypersignal T1 ≥ graisse qui persiste en T1 FS, souvent bilatéral et adhérent. C'est la localisation la plus fréquente de l'endométriose pelvienne.","s":[{"i":"definition","t":"Définition","x":"Implant endométriosique de l'ovaire < 1 cm ; endométriome au-delà de 1 cm."},{"i":"caracteristiques-du-kyste-endometriosique","t":"Caractéristiques du kyste endométriosique","x":"Contenu hémorragique, ± caillot intrakystique. Bilatéral (50 %), souvent multiple. Forme non arrondie. Paroi non vascularisée. Taille < 10 cm. Adhérences aux structures adjacentes, souvent en dedans et en arrière."},{"i":"imagerie","t":"Imagerie","x":"Échographie : formation kystique à contenu échogène en fin piqueté homogène ; matériel hyperéchogène interne = caillots ou cholestérol. IRM : hypersignal T1 ≥ graisse qui persiste en T1 FS ; hypersignal T2 ou shading T2. En cas de doute entre caillot et végétation : séquence injectée avec soustraction (un caillot ne se rehausse pas)."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Kystes à contenu échogène homogène : tumeur séreuse, salpinx, tumeur mucineuse, kyste dermoïde. Kystes ovariens en hypersignal T1 FS Origine · Lésions Lésion « secondaire » · Endométriome, abcès tubo-ovarien, torsion d'annexe irréversible Lésion primitive fonctionnelle · Kyste lutéal hémorragique, corps jaune Lésion primitive organique · Tumeur mucineuse (mucine), goitre ovarien (colloïde), tumeur de la granulosa (sang), tumeur endométrioïde et à cellules claires (sang), métastases (sang) Le kyste lutéal hémorragique reste en hypersignal T1 inférieur à la graisse, contrairement à l'endométriome."},{"i":"pieges","t":"Pièges","x":"Toute portion tissulaire dans un endométriome doit être explorée : caillot, décidualisation, transformation maligne, incarcération de franges tubaires, polype endométriosique. La diffusion n'est pas interprétable dans un contenu en hypersignal T1 : juger le rehaussement sur les soustractions."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Nombre, taille et latéralité des endométriomes, caillots, absence de portion tissulaire rehaussée, adhérences, autres localisations d'endométriose."}]},{"t":"Endométriome décidualisé","n":"Endométriome décidualisé","u":"endometriose/endometriome-decidualise.html","c":"Endométriose","b":"pendant la grossesse, un endométriome peut contenir une portion tissulaire vascularisée en hypersignal T2 franc. Il ne progresse pas pendant la grossesse et disparaît après l'accouchement.","s":[{"i":"definition","t":"Définition","x":"Imprégnation du tissu endométrial par la progestérone produite pendant la grossesse."},{"i":"contexte","t":"Contexte","x":"Grossesse évolutive."},{"i":"imagerie","t":"Imagerie","x":"Endométriome avec portion tissulaire intrakystique : végétation ou nodule. Échographie : portion solide endokystique échogène pseudo-végétante, avec vascularisation centrale au Doppler. IRM : nodules pariétaux endokystiques en hypersignal T2 franc ; le reste du kyste garde un signal endométriosique."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Causes d'endométriome avec portion solide : caillots intrakystiques ; transformation maligne ; décidualisation ; incarcération de franges tubaires ; polype endométriosique."},{"i":"criteres-en-faveur-de-la-decidualisation-tumeur-ovarienne-maligne","t":"Critères en faveur de la décidualisation (≠ tumeur ovarienne maligne)","x":"Pas de progression du kyste au cours de la grossesse. Disparition en post-partum."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Surveillance régulière pendant la grossesse, puis contrôle après l'accouchement."},{"i":"pieges","t":"Pièges","x":"Le hypersignal T2 franc des nodules est l'argument d'imagerie clé ; une portion tissulaire en signal T2 intermédiaire et en hypersignal diffusion doit faire craindre une transformation maligne."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille du kyste, nombre et taille des nodules, signal T2, vascularisation, comparaison aux examens antérieurs."}]},{"t":"Transformation maligne d'un endométriome","n":"Transformation maligne d'un endométriome","u":"endometriose/transformation-maligne-endometriome.html","c":"Endométriose","b":"un endométriome qui grossit, devient asymétrique ou développe une portion tissulaire vascularisée doit faire évoquer une transformation maligne.","s":[{"i":"definition","t":"Définition","x":"Transformation d'un endométriome en tumeur frontière ou invasive. Histologie : cancer ovarien épithélial à cellules claires, endométrioïde ou séreux de bas grade."},{"i":"terrain","t":"Terrain","x":"Endométriose connue ; femme plus jeune que pour les autres tumeurs épithéliales malignes."},{"i":"criteres-de-suspicion","t":"Critères de suspicion","x":"Taille > 10 cm. Asymétrie de taille par rapport aux autres endométriomes. Apparition de portions tissulaires."},{"i":"imagerie","t":"Imagerie","x":"Échographie : végétations ou nodules solides vascularisés au Doppler. IRM : portion tissulaire en hyposignal T1, signal T2 variable, hypersignal diffusion ; rehaussement visible sur les soustractions. Végétation + courbe de type 2 → tumeur frontière. Nodule solide + courbe de type 2 ou 3 → tumeur invasive."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Caillot intrakystique : pas de rehaussement sur les soustractions. Endométriome décidualisé : grossesse, nodules en hypersignal T2 franc, disparition en post-partum."},{"i":"pieges","t":"Pièges","x":"La diffusion n'est pas interprétable dans un contenu en hypersignal T1."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et évolution de l'endométriome, portion tissulaire (taille, signal T2, diffusion, courbe), comparaison aux autres endométriomes et aux examens antérieurs."}]},{"t":"Endométriose profonde : signes et localisations","n":"Endométriose profonde : signes et localisations","u":"endometriose/endometriose-profonde.html","c":"Endométriose","b":"l'endométriose profonde associe une composante glandulaire (signes directs, spécifiques) et une composante fibro-musculaire (signes indirects, sensibles). Elle est surtout postérieure.","s":[{"i":"definition","t":"Définition","x":"Tissu endométrial ectopique englobé par du tissu fibro-musculaire, en profondeur sous le péritoine, dans la paroi des organes ou à distance. Anatomopathologie : composante glandulaire et stroma endométrial, avec une hyperplasie fibro-musculaire réactionnelle."},{"i":"imagerie","t":"Imagerie","x":"Signes · Composante · Échographie · IRM Directs (spécifiques) · Glandulaire : images kystiques · Micro-kystes anéchogènes et/ou hyperéchogènes · Spots en hypersignal T2 et/ou T1 Indirects (sensibles) · Fibro-musculaire : fibrose, infiltration · Lésion iso- ou hypoéchogène · Lésion en hyposignal T2"},{"i":"localisations-preferentielles","t":"Localisations préférentielles","x":"Localisation · Fréquence Torus et ligaments utéro-sacrés · 75 % Recto-sigmoïde · 20 % Vagin · 15 % Vessie · 5 %"},{"i":"compartiments","t":"Compartiments","x":"Postérieur : torus, ligaments utéro-sacrés, vagin, cloison recto-vaginale, paroi digestive. Antérieur : vessie, cul-de-sac vésico-utérin, ligament rond. Latéral : paramètres, lame sacro-recto-génito-pubienne, paroi pelvienne, uretère."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Décrire chaque localisation par compartiment, avec sa taille en trois plans et ses rapports ; rechercher systématiquement une atteinte digestive et urinaire."}]},{"t":"Endométriose postérieure","n":"Endométriose postérieure","u":"endometriose/endometriose-posterieure.html","c":"Endométriose","b":"atteinte la plus fréquente de l'endométriose profonde, à partir des implants du cul-de-sac de Douglas. Le torus et les ligaments utéro-sacrés sont les premiers touchés.","s":[{"i":"definition","t":"Définition","x":"Atteinte des structures situées au contact ou en arrière de la paroi postérieure de l'utérus. Extension par continuité à partir des implants superficiels du péritoine du cul-de-sac de Douglas."},{"i":"localisations","t":"Localisations","x":"Torus, ligaments utéro-sacrés (LUS), paroi digestive, vagin, cloison recto-vaginale, adénomyose externe postérieure, ± symphyse complète du Douglas."},{"i":"torus-et-ligaments-utero-sacres","t":"Torus et ligaments utéro-sacrés","x":"Torus : partie postérieure et rétro-isthmique de l'utérus où se rejoignent les LUS. LUS : partie basse et antérieure des lames sacro-recto-génito-pubiennes ; normaux, ils sont réguliers et symétriques. Atteinte du torus : épaississement ou nodule irrégulier rétro-isthmique, au-dessus du cul-de-sac vaginal postérieur. Atteinte des LUS : épaississement irrégulier, asymétrique ou spiculé. Échographie : épaississement hypoéchogène ± micro-kystes. IRM : épaississement en hyposignal T2 ± implants en hypersignal T2 et/ou T1."},{"i":"vagin","t":"Vagin","x":"Rarement isolé ; clinique dominée par les dyschésies et les dyspareunies profondes. Nodule ou épaississement du cul-de-sac vaginal postérieur, ou épaississement localisé de la paroi vaginale > 5 mm. Échographie : épaississement hypoéchogène ± micro-kystes ; sonovaginographie (opacification vaginale) en cas de doute. IRM : épaississement en hyposignal T2 ± implants en hypersignal T1/T2."},{"i":"cloison-recto-vaginale","t":"Cloison recto-vaginale","x":"Nodule dans la graisse de la cloison recto-vaginale, sur la ligne médiane, sous la réflexion péritonéale du cul-de-sac de Douglas. Généralement associé à d'autres localisations (bas rectum, lame sacro-recto-génito-pubienne)."},{"i":"pieges","t":"Pièges","x":"Des LUS et un torus normaux ne sont pas visibles en échographie, sauf s'il existe un épanchement. Une atteinte postérieure doit faire chercher une atteinte digestive associée."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Torus, LUS (côté, épaisseur, extension latérale), vagin, cloison recto-vaginale, symphyse du Douglas, adénomyose externe postérieure."}]},{"t":"Endométriose digestive","n":"Endométriose digestive","u":"endometriose/endometriose-digestive.html","c":"Endométriose","b":"infiltration au moins de la musculeuse d'un segment digestif, le plus souvent le recto-sigmoïde. Il faut la distinguer d'une simple adhérence à la séreuse et la décrire de façon complète pour le chirurgien.","s":[{"i":"definition","t":"Définition","x":"Atteinte endométriosique sous-péritonéale qui infiltre au moins la musculeuse de la paroi d'un segment du tube digestif."},{"i":"localisations","t":"Localisations","x":"Recto-sigmoïde en premier ; iléon (23 %), cæcum (11 %), appendice (11 %). Multifocale : plusieurs lésions sur un même segment digestif. Multicentrique : lésions sur plusieurs segments digestifs. Association fréquente à une atteinte du torus et des LUS."},{"i":"imagerie","t":"Imagerie","x":"Effacement des espaces graisseux adjacents, souvent avec symphyse du cul-de-sac de Douglas. Masse ou épaississement pariétal digestif. Échographie : épaississement hypoéchogène de la musculeuse > 3 mm, linéaire ou nodulaire. IRM : épaississement de la paroi digestive en hyposignal T2 ± implants en hypersignal T2/T1 ; épaississement spiculé de la musculeuse."},{"i":"grele-et-cadre-colique","t":"Grêle et cadre colique","x":"Épaississement pariétal en hyposignal T2, prise de gadolinium, ± implants en hypersignal T2/T1. Entéro-IRM (pas de consensus) : endométriose sévère, atteinte du recto-sigmoïde, douleurs de la fosse iliaque droite."},{"i":"diagnostic-differentiel","t":"Diagnostic différentiel","x":"Adhérences à la séreuse sans atteinte de la musculeuse."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Recto-sigmoïde Confirmer l'atteinte (et non une adhérence). Segment atteint et distance à la marge anale. Degré d'infiltration pariétale (couche atteinte). Taille dans les 3 plans, épaisseur, circonférence atteinte. Multifocalité et/ou multicentricité. Degré de sténose digestive. Autres localisations profondes. Grêle et cadre colique Épaisseur, longueur, circonférence, distance par rapport à la jonction iléo-cæcale."}]},{"t":"Endométriose antérieure","n":"Endométriose antérieure","u":"endometriose/endometriose-anterieure.html","c":"Endométriose","b":"atteinte à partir du cul-de-sac vésico-utérin, dominée par l'atteinte de la musculeuse vésicale ; rechercher une urétéro-hydronéphrose.","s":[{"i":"definition","t":"Définition","x":"Atteinte des structures situées au contact ou en avant de la paroi antérieure de l'utérus. Extension par continuité à partir des implants superficiels du péritoine du cul-de-sac vésico-utérin."},{"i":"clinique","t":"Clinique","x":"Dysuries menstruelles, cystites, douleurs mictionnelles."},{"i":"histoire-naturelle","t":"Histoire naturelle","x":"Atteinte péritonéale superficielle du cul-de-sac vésico-utérin. Extension en profondeur : atteinte de la paroi vésicale. Extension locorégionale : adénomyose externe antérieure, ligament rond (atteinte latérale)."},{"i":"vessie","t":"Vessie","x":"Épaississement linéaire ou nodulaire de la musculeuse vésicale. Échographie : hypoéchogène ± micro-kystes. IRM : hyposignal T2 ± implants en hypersignal T1/T2. Signes associés : disparition et comblement du cul-de-sac vésico-utérin, ± atteinte des ligaments ronds, ± adénomyose externe antérieure."},{"i":"complication","t":"Complication","x":"Urétéro-hydronéphrose par atteinte des méats urétéro-vésicaux."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Siège et taille du nodule vésical, profondeur d'atteinte de la paroi, distance aux méats urétéraux, cavités rénales, ligaments ronds, adénomyose associée."}]},{"t":"Endométriose latérale","n":"Endométriose latérale","u":"endometriose/endometriose-laterale.html","c":"Endométriose","b":"atteinte des ligaments ronds, des paramètres, de la lame sacro-recto-génito-pubienne et de la paroi pelvienne. Ses deux complications sont l'urétéro-hydronéphrose et les douleurs neuropathiques.","s":[{"i":"definition","t":"Définition","x":"Atteinte endométriosique des structures situées latéralement."},{"i":"localisations","t":"Localisations","x":"Ligaments ronds Atteinte généralement proximale, cornuale, plus souvent à droite ; uni- ou bilatérale. Lésion nodulaire ± spots en hypersignal T1 ou T2. Atteinte distale possible du canal de Nuck ou de la région vulvaire. Paramètres Signes directs : lésion en hyposignal T2 ± spots en hypersignal T1/T2, para-cervicale ou para-vaginale. Signes indirects : dilatation urétérale. Lame sacro-recto-génito-pubienne (LSRGP) Atteinte généralement dans le prolongement distal des ligaments utéro-sacrés. Paroi pelvienne Atteinte isolée ou en continuité du paramètre ; possible atteinte du plexus hypogastrique."},{"i":"complications","t":"Complications","x":"Urétéro-hydronéphrose par envahissement urétéral (segment paramétrial). Sciatalgies et douleurs neuropathiques par envahissement des nerfs sciatiques et des plexus sacrés."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Côté, siège et taille des lésions, rapport avec l'uretère, dilatation urétérale et cavités rénales, extension à la paroi pelvienne et aux nerfs."}]},{"t":"Endométriose du péritoine pelvien","n":"Endométriose du péritoine pelvien","u":"endometriose/peritoine-pelvien.html","c":"Endométriose","b":"atteinte superficielle du péritoine sous trois formes, implants, adhérences et collections. La forme la plus sévère est la symphyse complète du cul-de-sac de Douglas.","s":[{"i":"implants-peritoneaux-superficiels","t":"Implants péritonéaux superficiels","x":"Implants < 4 mm, kystiques ou hémorragiques, ± nodule de réaction fibro-musculaire."},{"i":"adherences-pelviennes","t":"Adhérences pelviennes","x":"Bandes linéaires en hyposignal T2. Modification des rapports anatomiques entre les organes. Forme la plus sévère : symphyse complète du cul-de-sac de Douglas."},{"i":"collections-peritoneales-pseudo-kyste-peritoneal","t":"Collections péritonéales : pseudo-kyste péritonéal","x":"Collection intrapéritonéale quadrangulaire qui moule les organes de voisinage. Déformable à la palpation en échographie. ± contenu endométriosique."},{"i":"pieges","t":"Pièges","x":"Un pseudo-kyste péritonéal ne doit pas être pris pour un kyste ovarien : l'ovaire est en bordure ou à l'intérieur de la collection."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Implants, adhérences (organes concernés), symphyse du Douglas, pseudo-kystes péritonéaux."}]},{"t":"Endométriose : localisations rares","n":"Localisations rares","u":"endometriose/localisations-rares.html","c":"Endométriose","b":"diaphragme, trompe, paroi abdominale et périnée. Le nodule en hyposignal T2 avec des spots en hypersignal T1/T2 est pathognomonique.","s":[{"i":"atteinte-sus-mesocolique-peritoneale","t":"Atteinte sus-mésocolique péritonéale","x":"Coupole diaphragmatique droite surtout. Clinique : scapulalgies droites cataméniales. IRM : séquences T1 FS dans 3 plans centrées sur les coupoles ; implants en hypersignal T1."},{"i":"atteinte-tubaire","t":"Atteinte tubaire","x":"Hystérosalpingographie : examen de référence. En IRM, difficile à distinguer d'une localisation ovarienne. Hématosalpinx de signal endométriosique."},{"i":"paroi-abdominale","t":"Paroi abdominale","x":"Nodule en hyposignal T2 avec spots en hypersignal T1/T2 : aspect pathognomonique. Possible sur tous les orifices de trocart, de cœlioscopie, de césarienne. Diagnostic différentiel : tumeur desmoïde."},{"i":"perinee","t":"Périnée","x":"Sur cicatrice, d'épisiotomie surtout : nodule spiculé avec implants en hypersignal T1."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Siège, taille, rapport avec les plans musculaires et aponévrotiques, cicatrice en cause."}]},{"t":"Infection génitale haute et salpingite aiguë","n":"Infection génitale haute et salpingite aiguë","u":"trompe/infection-genitale-haute-salpingite.html","c":"Trompe","b":"le diagnostic d'infection génitale haute (IGH) est clinique et bactériologique. Une imagerie normale ou l'absence de syndrome inflammatoire ne l'excluent pas ; l'imagerie sert surtout à chercher une complication.","s":[{"i":"definition-et-terrain","t":"Définition et terrain","x":"Atteinte infectieuse aiguë ou chronique des trompes, ± des ovaires, de l'utérus et du péritoine. Fréquente, chez la femme jeune sexuellement active. Germes principaux : Chlamydia trachomatis, Neisseria gonorrhoeae. Infection ascendante : col, endomètre, trompes, puis ovaires et péritoine."},{"i":"imagerie-de-la-salpingite-aigue","t":"Imagerie de la salpingite aiguë","x":"Souvent pauvre ou normale au stade de salpingite simple. Trompe visible car épaissie et congestive, hyperhémie au Doppler. En coupe transversale, plis muqueux épaissis donnant un aspect en roue dentée. Infiltration de la graisse pelvienne, épanchement du cul-de-sac de Douglas. Ovaire augmenté de volume et œdématié en cas d'ovarite associée."},{"i":"complications","t":"Complications","x":"Aiguës · Chroniques Pyosalpinx, abcès tubo-ovarien · Adhérences Thrombose veineuse ovarienne · Hydrosalpinx, pseudo-kyste péritonéal Péri-hépatite de Fitz-Hugh-Curtis · Hypofertilité, grossesse extra-utérine Péritonite, choc septique · Douleurs pelviennes chroniques"},{"i":"syndrome-de-fitz-hugh-curtis","t":"Syndrome de Fitz-Hugh-Curtis","x":"Inflammation de la capsule hépatique et du foie adjacent (péri-hépatite), par diffusion péritonéale le long de la gouttière pariéto-colique droite ; Chlamydia trachomatis surtout. Scanner : hyper-rehaussement de la capsule hépatique antérieure au temps artériel, surtout sur le foie droit, avec épargne de l'area nuda (face postérieure, non péritonéalisée) ; ± épanchement et adhérences péri-hépatiques. Réflexe : douleur de l'hypochondre droit + sepsis chez une femme jeune → ajouter une acquisition hépatique au temps artériel tardif (environ 35 s)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Toute suspicion clinique : prélèvements bactériologiques et antibiothérapie sans attendre l'imagerie. Échographie endovaginale en première intention pour chercher une collection ; IRM ou scanner si doute ou forme compliquée."},{"i":"pieges","t":"Pièges","x":"Une échographie normale n'élimine pas une salpingite. Douleur de l'hypochondre droit chez une femme jeune : penser au Fitz-Hugh-Curtis avant la cholécystite."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Trompes (calibre, paroi, contenu), ovaires, collection, épanchement, veines ovariennes, capsule hépatique si scanner."}]},{"t":"Pyosalpinx et abcès tubo-ovarien","n":"Pyosalpinx et abcès tubo-ovarien","u":"trompe/pyosalpinx-abces-tubo-ovarien.html","c":"Trompe","b":"le pyosalpinx est une trompe distendue par du pus, encore distincte de l'ovaire. Quand trompe et ovaire ne se distinguent plus dans une masse complexe, c'est un abcès tubo-ovarien.","s":[{"i":"pyosalpinx","t":"Pyosalpinx","x":"Définition : rétention purulente intratubaire. Échographie en première intention, IRM en deuxième intention. Collection tubulée latéro-utérine, de calibre augmenté, avec franges tubaires visibles. Contenu hétérogène, échogène en échographie, sédiment échogène avasculaire ; en IRM, signal T2 « sale » et restriction de la diffusion ; ± niveau liquide-liquide, ± gaz. Paroi tubaire épaissie, hyperhémique au Doppler. Ovarite possible : ovaire augmenté de volume, œdématié, stroma hyperhémique. À ce stade, ovaires et trompes restent distincts."},{"i":"abces-tubo-ovarien","t":"Abcès tubo-ovarien","x":"Définition : collection purulente développée aux dépens des annexes. Masse complexe mixte, uni- ou multiloculaire, latéro-utérine. Paroi épaisse vascularisée ; coque interne en hyposignal T2 et en hypersignal T1. Cloisons épaisses vascularisées. Contenu purulent : signal T2 « sale » hétérogène (shading), restriction de diffusion, ± niveau liquide-liquide ou hydro-aérique. Rehaussement pariétal intense, supérieur ou égal au myomètre. Infiltration de la graisse sous-péritonéale autour de la lésion, épanchement pelvien libre ou cloisonné. À ce stade, ovaires et trompes sont indistincts."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Lésions ovariennes kystiques à paroi épaisse : corps jaune et kyste lutéal hémorragique, torsion d'annexe, abcès tubo-ovarien. Endométriome surinfecté, tumeur ovarienne nécrosée, abcès d'origine digestive (appendicite, sigmoïdite)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Antibiothérapie ; drainage guidé par l'imagerie (voie transvaginale ou percutanée) ou chirurgie en cas d'abcès volumineux ou d'échec du traitement médical."},{"i":"pieges","t":"Pièges","x":"Une masse complexe à paroi épaisse dans un contexte fébrile ne doit pas être classée comme tumeur : le contexte infectieux et la restriction de diffusion du contenu orientent. Chercher une cause digestive (appendice, sigmoïde) devant un abcès pelvien."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Latéralité, taille, distinction trompe/ovaire, gaz, épanchement, thrombose veineuse ovarienne, accessibilité à un drainage."}]},{"t":"Actinomycose pelvienne","n":"Actinomycose","u":"trompe/actinomycose.html","c":"Trompe","b":"masse pelvienne infiltrante pseudo-tumorale, ± sepsis, chez une patiente porteuse d'un stérilet (DIU) : évoquer l'actinomycose.","s":[{"i":"definition","t":"Définition","x":"Infection chronique rare à Actinomyces (israelii surtout), bacille Gram positif anaérobie. Localisations : ORL (55 à 63 %), abdomen et pelvis (22 %), thorax (15 %). Mécanisme : effraction muqueuse puis colonisation profonde ; l'infection traverse les plans anatomiques sans les respecter."},{"i":"terrain-et-clinique","t":"Terrain et clinique","x":"DIU surtout, ou pessaire, chirurgie pelvienne, cancer. Évolution subaiguë ou chronique ; douleur, fièvre, altération de l'état général, métrorragies, leucorrhées ; hyperleucocytose fréquente."},{"i":"imagerie-irm-et-ou-scanner","t":"Imagerie (IRM et/ou scanner)","x":"Masses pelviennes solides complexes et hétérogènes, avec abcès multiples ou centraux. Aspect pseudo-tumoral, infiltrant et rétractile ; collections en signal T2 intermédiaire « sale ». Atteinte pré-sacrée et du mésorectum très évocatrice ; fistules possibles. Rehaussement de la graisse péri-lésionnelle, adhérences, épanchement."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Cancer pelvien : adénomégalies, ± métastases ; histologie. Maladie de Crohn : contexte, pas de masse, atteinte digestive et extra-digestive. Tuberculose génitale ou digestive : atteinte extra-pelvienne, adénopathies nécrotiques."},{"i":"pieges","t":"Pièges","x":"Le caractère infiltrant qui franchit les plans fait penser à un cancer : penser à regarder s'il y a un DIU."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Présence et position du DIU, extension (mésorectum, espace pré-sacré, paroi), abcès drainables, fistules, uretères."}]},{"t":"Tuberculose pelvienne","n":"Tuberculose pelvienne","u":"trompe/tuberculose-pelvienne.html","c":"Trompe","b":"atteinte tubo-ovarienne bilatérale avec péritoine épaissi de façon lisse et ganglions nécrotiques ou calcifiés ; elle peut imiter un cancer ovarien avec carcinose et un CA 125 élevé.","s":[{"i":"terrain","t":"Terrain","x":"Infection chronique rare à Mycobacterium tuberculosis ; l'atteinte génitale représente 1,3 % des tuberculoses. Organes atteints : endomètre (72 %), trompes (34 %), ovaires (13 %), col (2 %). Contamination hémato-lymphatique, plus rarement par dissémination péritonéale ; formes systémiques favorisées par l'immunodépression (VIH). Clinique peu spécifique : douleur, fébricule, altération de l'état général, métrorragies, leucorrhées ; CA 125 souvent élevé."},{"i":"imagerie","t":"Imagerie","x":"Atteinte tubo-ovarienne (bilatérale, extension transpéritonéale) Salpingite : épaississement diffus ou nodulaire des parois tubaires. Pyosalpinx ou hydrosalpinx. Abcès tubo-ovarien à paroi interne épaisse et irrégulière (nodulaire, crantée), en hyposignal T2, ± calcifications. Atteinte péritonéale Épaississement péritonéal lisse avec prise de contraste linéaire, adhérences. Infiltration micronodulaire ou striée du grand omentum, infiltration micronodulaire du mésentère. Ascite. Atteinte ganglionnaire Ganglions nécrotiques, parfois confluents, ± fistulisation, ± calcifications. Stade chronique Sténoses cicatricielles : hydrosalpinx bilatéraux et multifocaux, synéchies endométriales ou cervicales ; risque d'hypofertilité."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Cancer ovarien avec carcinose : épaississement péritonéal nodulaire, adénopathies non nécrotiques. Abcès tubo-ovarien à pyogènes : sepsis plus marqué, atteinte péritonéale moins importante."},{"i":"signes-cles","t":"Signes clés","x":"Les atteintes extra-gynécologiques, péritonéales et ganglionnaires, sont les meilleurs arguments diagnostiques."},{"i":"pieges","t":"Pièges","x":"Ascite + masse annexielle + CA 125 élevé n'est pas toujours un cancer : penser à la tuberculose devant un péritoine épaissi de façon lisse et des ganglions nécrotiques."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Atteinte tubo-ovarienne (uni- ou bilatérale), aspect du péritoine (lisse ou nodulaire), omentum, ascite, ganglions (nécrose, calcifications), endomètre, atteinte pulmonaire si scanner thoracique."}]},{"t":"Hydrosalpinx","n":"Hydrosalpinx","u":"trompe/hydrosalpinx.html","c":"Trompe","b":"collection tubulée péri-ovarienne, en C ou en S, avec des cloisons incomplètes, séparée de l'ovaire. C'est une cause d'hypofertilité ; il faut toujours chercher l'obstacle.","s":[{"i":"definition","t":"Définition","x":"Distension de la trompe par accumulation de liquide séreux en amont d'une sténose ou d'une obstruction."},{"i":"terrain","t":"Terrain","x":"Antécédent d'infection génitale haute, de chirurgie ou d'irradiation pelvienne, endométriose. Cause d'hypofertilité."},{"i":"imagerie","t":"Imagerie","x":"Collection péri-ovarienne tubulée, serpigineuse, en C ou en S. Cloisons incomplètes : ce sont les replis de la trompe sur elle-même. Franges tubaires hypertrophiques au stade chronique, visibles en coupe transversale comme de petites saillies de la paroi (aspect en chapelet). Ovaire homolatéral indépendant de la masse. IRM : contenu en hypersignal T2 ; un contenu en hypersignal T1 FS évoque un hématosalpinx."},{"i":"causes","t":"Causes","x":"Adhérences post-infectieuses ou postopératoires, endométriose. Tumeur tubaire. Torsion d'annexe ou torsion tubaire isolée."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Lésion · Argument Masse kystique ovarienne · Forme non tubulée, ovaire non visible séparément ou refoulé Pseudo-kyste péritonéal · Paroi non frangée, pas de forme propre, moule les structures sans les refouler, déformable à la palpation Kyste paratubaire · Rond ou ovale, paroi non frangée"},{"i":"pieges","t":"Pièges","x":"Sur une seule coupe, un hydrosalpinx replié peut simuler une masse ovarienne multiloculaire : suivre la structure dans plusieurs plans pour voir sa forme tubulée. Toute portion tissulaire dans un hydrosalpinx doit faire chercher un carcinome tubaire."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Latéralité, calibre maximal, contenu (séreux, hématique, purulent), paroi, portion tissulaire, ovaire homolatéral, cause suspectée."}]},{"t":"Carcinome tubaire","n":"Carcinome tubaire","u":"trompe/carcinome-tubaire.html","c":"Trompe","b":"bourgeon tissulaire vascularisé dans une trompe dilatée, chez une femme ménopausée qui se plaint de pertes séro-sanglantes. Rare, sauf en cas de mutation BRCA.","s":[{"i":"definition","t":"Définition","x":"Tumeur épithéliale primitive de la trompe : adénocarcinome, le plus souvent séreux papillaire."},{"i":"terrain-et-clinique","t":"Terrain et clinique","x":"Rare (0,3 % des cancers gynécologiques), sauf mutation BRCA (BRCA1 plus que BRCA2). Prédominance après la ménopause ; bilatéral dans 20 % des cas. Clinique peu spécifique : douleurs pelviennes, hydrorrhée (pertes vaginales séro-sanglantes), masse pelvienne."},{"i":"imagerie","t":"Imagerie","x":"Masse ou végétation murale tissulaire au sein d'une trompe dilatée (hydrosalpinx ou hématosalpinx, par sécrétion tumorale ± obstruction). Échographie : bourgeon échogène vascularisé au Doppler. IRM : signal T2 intermédiaire, hypersignal diffusion, rehaussement de type 2 ou 3, ± remaniements hémorragiques. Épanchement péri-annexiel : vidange de l'hydrosalpinx et/ou carcinose."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Carcinome ovarien : portion kystique non tubulée. Léiomyome tubaire : hyposignal T2, faible rehaussement. Métastases tubaires : atteinte bilatérale, cancer primitif connu. Abcès : sepsis, atteinte bilatérale, pas de masse tissulaire."},{"i":"a-savoir","t":"À savoir","x":"Beaucoup de carcinomes séreux de haut grade dits « ovariens » naissent en réalité du pavillon de la trompe ; le carcinome tubaire isolé visible en imagerie reste rare."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Latéralité, taille du bourgeon, signal et courbe, calibre de la trompe, ovaire homolatéral, épanchement, carcinose, adénopathies."}]},{"t":"Grossesse extra-utérine","n":"Grossesse extra-utérine","u":"trompe/grossesse-extra-uterine.html","c":"Trompe","b":"douleur pelvienne aiguë ou métrorragies chez une femme en âge de procréer = grossesse extra-utérine (GEU) jusqu'à preuve du contraire. Le diagnostic repose sur le couple échographie endovaginale et hCG plasmatique.","s":[{"i":"definition","t":"Définition","x":"Implantation d'un sac gestationnel en dehors de la cavité utérine."},{"i":"facteurs-de-risque","t":"Facteurs de risque","x":"Antécédent de GEU, d'infection génitale haute, de chirurgie tubaire ; procréation médicalement assistée. Tabac, endométriose, malformations utéro-annexielles."},{"i":"localisations","t":"Localisations","x":"Tubaire dans 95 % des cas : ampullaire surtout (70 à 80 %), isthmique (environ 10 %), pavillonnaire, interstitielle. Rares : ovarienne, cervicale, sur cicatrice de césarienne, abdominale."},{"i":"imagerie","t":"Imagerie","x":"Triade : hCG > 1500 à 2000 UI/L + utérus vide + masse annexielle extra-ovarienne. Élément · Aspect Vacuité utérine · Pas de sac gestationnel (visible normalement dès 5 SA) ; ± pseudo-sac, non spécifique Masse annexielle extra-ovarienne · Hématosalpinx ; ± sac extra-utérin = collection à couronne hyperéchogène (« tubal ring sign ») et hypervasculaire (« ring of fire ») ; ± vésicule vitelline, ± embryon Endomètre · Épais, décidualisé, en triple feuillet, ± kystes déciduaux Hémopéritoine · Épanchement échogène ; au scanner densité spontanée > 40–50 UH Corps jaune · Paroi épaisse hypervasculaire, contenu variable, souvent du même côté Astuce : la masse de la GEU est séparée de l'ovaire et bouge indépendamment de lui sous la sonde ; le corps jaune est dans l'ovaire."},{"i":"vacuite-uterine-avec-hcg-positifs","t":"Vacuité utérine avec hCG positifs","x":"Situation · Interprétation hCG > 1500 UI/L et masse annexielle · GEU probable hCG > 1500 UI/L sans masse annexielle · GEU possible hCG < 1500 UI/L · Grossesse de localisation indéterminée (grossesse intra-utérine précoce, fausse couche ou GEU) : contrôle à 48 h IRM en cas de suspicion de localisation interstitielle."},{"i":"sac-gestationnel-intra-uterin-et-faux-sacs","t":"Sac gestationnel intra-utérin et faux sacs","x":"Structure · Aspect Sac gestationnel (dès 5–6 SA) · Unique, intra-endométrial, excentré, couronne hyperéchogène ; vésicule vitelline entre 5 et 6 SA Pseudo-sac · Intracavitaire, central, sans couronne, peu tonique Kyste décidual · À la jonction endomètre-myomètre, sans couronne, souvent multiples Repères en pratique Un sac gestationnel > 10 mm contient normalement une vésicule vitelline. Un sac gestationnel > 16 mm contient normalement un embryon. Un embryon > 4 mm a normalement une activité cardiaque. Ces repères imposent un contrôle ; le diagnostic formel de grossesse arrêtée repose sur des seuils plus stricts (sac ≥ 25 mm sans embryon, embryon ≥ 7 mm sans activité cardiaque)."},{"i":"pieges","t":"Pièges","x":"Un hématosalpinx isolé chez une femme en âge de procréer = GEU jusqu'à preuve du contraire. Autres causes : endométriose tubaire, tumeur tubaire, torsion tubaire isolée. Un pseudo-sac ne doit pas être pris pour un sac gestationnel : pas de couronne, position centrale dans la cavité. Une grossesse hétérotopique (intra- et extra-utérine) est possible, surtout après procréation médicalement assistée."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Contenu de la cavité utérine, endomètre, masse annexielle (côté, taille, sac, vésicule, embryon, activité cardiaque), position du corps jaune, abondance de l'hémopéritoine."}]},{"t":"Torsion tubaire isolée","n":"Torsion tubaire isolée","u":"trompe/torsion-tubaire-isolee.html","c":"Trompe","b":"douleur pelvienne aiguë sans fièvre + hydro- ou hématosalpinx unilatéral + ovaire normal + hCG négatifs. Cherchez le tour de spire à côté de l'ovaire.","s":[{"i":"definition","t":"Définition","x":"Torsion de la trompe autour de son axe ou de son mésosalpinx, sans torsion de l'ovaire."},{"i":"terrain","t":"Terrain","x":"Exceptionnelle ; femme jeune, souvent avant 25 ans. Facteurs de risque : hydrosalpinx, kyste paratubaire."},{"i":"mecanisme","t":"Mécanisme","x":"Torsion, occlusion veino-lymphatique, puis congestion tubaire passive."},{"i":"imagerie","t":"Imagerie","x":"Hématosalpinx ou hydrosalpinx unilatéral. Ovaire normal. Tour de spire vasculaire para-ovarien. ± masse ovarienne ou paratubaire."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Torsion d'annexe : ovaire augmenté de volume et œdématié. Grossesse extra-utérine : hCG positifs. Pyosalpinx : fièvre, contexte infectieux."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Avis chirurgical urgent pour une détorsion."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Côté, calibre et contenu de la trompe, tour de spire, aspect de l'ovaire homolatéral, kyste paratubaire associé."}]},{"t":"Endomètre normal","n":"Endomètre normal","u":"endometre-col/endometre-normal.html","c":"Endomètre et col","b":"l'épaisseur et l'échostructure de l'endomètre changent avec l'âge et le cycle. Un endomètre ne se juge jamais sans connaître la date du cycle ou le statut ménopausique.","s":[{"i":"definition","t":"Définition","x":"Muqueuse faite de cellules épithéliales et d'un chorion cytogène, sous l'influence des hormones stéroïdes."},{"i":"technique","t":"Technique","x":"Échographie endovaginale en première intention ; IRM en deuxième intention, surtout pour la pathologie maligne. Épaisseur mesurée sur une coupe sagittale médiane, d'une interface endomètre-myomètre à l'autre (deux feuillets), en excluant le liquide intracavitaire."},{"i":"aspect-echographique-selon-la-periode","t":"Aspect échographique selon la période","x":"Période · Aspect · Épaisseur Pré-pubertaire · Fin, échogène · ≈ 1 mm Menstruelle (J1–J4) · Double ou triple feuillet · 1 à 4 mm Proliférative (J5–J14) · Hypoéchogène, triple feuillet · 5 à 7 mm Péri-ovulatoire (J14–J15) · Triple feuillet net · Jusqu'à 11 mm Sécrétoire (J16–J28) · Hyperéchogène, homogène · 7 à 16 mm Ménopause · Fin, hyperéchogène · < 5 mm"},{"i":"irm-en-periode-d-activite-genitale","t":"IRM en période d'activité génitale","x":"Endomètre en hypersignal T2, bordé par la zone jonctionnelle en hyposignal T2 (myomètre interne). Hypersignal diffusion physiologique ; ADC normal entre 1,25 et 1,5 × 10⁻³ mm²/s."},{"i":"seuils-d-epaississement-a-retenir","t":"Seuils d'épaississement à retenir","x":"Femme ménopausée : ≥ 5 mm. Femme non ménopausée : ≥ 16 mm, à contrôler en début de cycle."},{"i":"pieges","t":"Pièges","x":"Un endomètre sécrétoire épais et hyperéchogène est normal en fin de cycle : refaire l'échographie en début de cycle (J1–J4) en cas de doute. Le liquide intracavitaire ne doit pas être inclus dans la mesure."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Date des dernières règles ou statut ménopausique, traitement hormonal, épaisseur (deux feuillets), échostructure, interface endomètre-myomètre, vascularisation."}]},{"t":"Atrophie endométriale","n":"Atrophie endométriale","u":"endometre-col/atrophie-endometriale.html","c":"Endomètre et col","b":"première cause de saignements après la ménopause. Un endomètre fin et régulier (≤ 4 mm) a une excellente valeur prédictive négative pour le cancer.","s":[{"i":"definition","t":"Définition","x":"Amincissement de la muqueuse par carence en œstrogènes : ménopause, insuffisance ovarienne prématurée ou post-thérapeutique, pilule minidosée ou progestatif pur au long cours."},{"i":"clinique","t":"Clinique","x":"Première cause de saignements post-ménopausiques ; moins fréquente sous traitement hormonal de la ménopause."},{"i":"imagerie","t":"Imagerie","x":"Épaisseur endométriale ≤ 4 mm, ± petite rétention liquidienne. Utérus de petite taille. Doppler de l'artère utérine : haute résistance (IR > 0,95, IP > 3), diastole nulle."},{"i":"forme-particuliere-atrophie-kystique-sous-tamoxifene","t":"Forme particulière : atrophie kystique sous Tamoxifène","x":"Pseudo-épaississement multikystique de l'endomètre, cerné d'un fin liseré échogène, sans vascularisation au Doppler. Les kystes sont en réalité sous-endométriaux : la muqueuse elle-même reste fine."},{"i":"effets-du-tamoxifene-sur-l-uterus","t":"Effets du Tamoxifène sur l'utérus","x":"Effet agoniste œstrogénique sur l'endomètre. Atrophie endométriale, kystique ou non. Polypes endométriaux. Réactivation d'une adénomyose. Risque augmenté d'hyperplasie et de cancer de l'endomètre."},{"i":"pieges","t":"Pièges","x":"Sous Tamoxifène, l'épaisseur mesurée surestime l'endomètre : en cas de saignement, l'hystéroscopie tranche."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Épaisseur, régularité, liquide intracavitaire, aspect kystique, vascularisation, traitement en cours."}]},{"t":"Hypertrophie endométriale d'allure bénigne","n":"Hypertrophie endométriale d'allure bénigne","u":"endometre-col/hypertrophie-endometriale.html","c":"Endomètre et col","b":"un épaississement régulier, homogène, non vascularisé, avec une interface endomètre-myomètre nette, est d'allure bénigne. Mais aucun critère d'imagerie ne distingue hyperplasie simple, complexe ou atypique : saignements + épaississement = biopsie.","s":[{"i":"definition","t":"Définition","x":"Prolifération endométriale anormale, diffuse (rarement focale), non carcinomateuse, avec ou sans atypie."},{"i":"terrain","t":"Terrain","x":"Hyperœstrogénie : obésité, nulliparité, Tamoxifène, anovulation, tumeur ovarienne sécrétante ; HTA, diabète. Clinique : saignements."},{"i":"seuils-d-epaississement","t":"Seuils d'épaississement","x":"Femme ménopausée : ≥ 5 mm. Femme non ménopausée : ≥ 16 mm."},{"i":"criteres-en-faveur-de-la-benignite","t":"Critères en faveur de la bénignité","x":"Épaississement régulier et homogène (échogène, hypersignal T2). Pas de vascularisation au Doppler énergie. ± microkystes (aspect glandulo-kystique). Interface endomètre-myomètre régulière, sans signe d'envahissement du myomètre. Rehaussement important sur les séquences T1 tardives après gadolinium. ADC ≥ 1,4 × 10⁻³ mm²/s."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Adénocarcinome de l'endomètre : masse en signal T2 intermédiaire, ADC bas, interface irrégulière. Polype : lésion focale avec pédicule vasculaire. Endomètre sécrétoire normal chez la femme jeune."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Femme non ménopausée, endomètre ≥ 16 mm : contrôle en début de cycle. Femme ménopausée, endomètre ≥ 5 mm : hystéroscopie et biopsie."},{"i":"pieges","t":"Pièges","x":"L'hypersignal diffusion de l'endomètre n'est pas discriminant : c'est l'ADC qu'il faut regarder. Chez une femme ménopausée avec un endomètre épais, regarder les ovaires : une tumeur de la granulosa peut être en cause."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Épaisseur, régularité, homogénéité, microkystes, vascularisation, interface, ADC si IRM, ovaires."}]},{"t":"Polype endométrial","n":"Polype endométrial","u":"endometre-col/polype-endometrial.html","c":"Endomètre et col","b":"masse intracavitaire à contours lisses avec un pédicule vasculaire artériel central au Doppler. Le Doppler est l'examen clé, et l'échographie se fait en début de cycle.","s":[{"i":"definition","t":"Définition","x":"Expansion nodulaire focale intracavitaire de la muqueuse endométriale, à base sessile ou pédiculée, avec un stroma plus ou moins fibreux."},{"i":"terrain","t":"Terrain","x":"Femme ménopausée surtout ; saignements ; Tamoxifène."},{"i":"imagerie","t":"Imagerie","x":"Masse intracavitaire, contours lisses et réguliers, homogène ± microkystes. Critère principal : pédicule vasculaire artériel central au Doppler. Interface endomètre-myomètre continue et régulière, myomètre intact. IRM : faible restriction de diffusion, rehaussement homogène au temps artériel. Échographie à réaliser en début de cycle (J1–J4), quand l'endomètre est fin."},{"i":"diagnostic-differentiel-myome-intracavitaire-figo-0","t":"Diagnostic différentiel : myome intracavitaire (FIGO 0)","x":"Critère · Polype · Myome FIGO 0 Vascularisation · Pédicule central · Annulaire, en encorbellement Échogénicité · Souvent hyperéchogène · Hypoéchogène, avec cônes d'ombre Signal T2 · Intermédiaire à élevé · Hyposignal (s'il est hyalin) Rehaussement · Homogène, artériel · Parallèle au myomètre (type 2) Autres diagnostics différentiels : hyperplasie focale, cancer de l'endomètre (interface irrégulière, ADC bas), caillot (non vascularisé)."},{"i":"pieges","t":"Pièges","x":"Un caillot peut simuler un polype : il n'a pas de pédicule vasculaire. Un polype volumineux et hétérogène chez une femme ménopausée doit être retiré et analysé."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Nombre, taille, base d'implantation, pédicule vasculaire, interface avec le myomètre, épaisseur de l'endomètre adjacent."}]},{"t":"Synéchie utérine","n":"Synéchie utérine","u":"endometre-col/synechie-uterine.html","c":"Endomètre et col","b":"accolement des parois de la cavité utérine après un traumatisme ou une infection. L'hystéroscopie fait le diagnostic et le traitement.","s":[{"i":"definition","t":"Définition","x":"Accolement de deux feuillets endométriaux, post-traumatique (curetage, chirurgie) ou post-infectieux (dont tuberculose)."},{"i":"clinique","t":"Clinique","x":"Hypoménorrhée ou aménorrhée, infertilité, fausses couches à répétition."},{"i":"imagerie","t":"Imagerie","x":"Hystéroscopie : examen de référence, diagnostique et thérapeutique. Hystérosalpingographie : image effilée « en doigt de gant » ou lacune irrégulière de la cavité. Échographie : interruption de la ligne endométriale, étendue ou non ; mieux vue en phase sécrétoire ou après instillation de sérum dans la cavité."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Malformation utérine (cloison), polype, myome sous-muqueux."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Siège et étendue de l'atteinte de la cavité, épaisseur de l'endomètre restant."}]},{"t":"Saignements après la ménopause : démarche","n":"Saignements après la ménopause : démarche","u":"endometre-col/saignements-apres-menopause.html","c":"Endomètre et col","b":"métrorragies post-ménopausiques = cancer de l'endomètre jusqu'à preuve du contraire. L'échographie trie : un endomètre < 5 mm rassure, un endomètre ≥ 5 mm impose une hystéroscopie avec biopsie.","s":[{"i":"demarche","t":"Démarche","x":"Échographie pelvienne, sus-pubienne et endovaginale. Endomètre < 5 mm : pas de cancer de l'endomètre dans la grande majorité des cas (bonne valeur prédictive négative), cause la plus fréquente l'atrophie. Endomètre ≥ 5 mm, avec ou sans traitement hormonal de la ménopause : hystéroscopie et biopsie. Biopsie maligne : IRM pelvienne (extension locale et ganglionnaire) et scanner thoraco-abdomino-pelvien (ganglions et métastases)."},{"i":"causes-a-chercher","t":"Causes à chercher","x":"Organe · Causes Endomètre · Atrophie, polype, hyperplasie, cancer Myomètre · Myome sous-muqueux, adénomyose Col · Lésion cervicale Annexes · Cancer tubaire, tumeur ovarienne sécrétant des œstrogènes (granulosa)"},{"i":"pieges","t":"Pièges","x":"Un endomètre fin n'élimine pas un cancer s'il est mal vu, irrégulier, ou si les saignements persistent: la biopsie reste indiquée. Toujours regarder les ovaires et le col."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Épaisseur de l'endomètre (deux feuillets), régularité, lésion focale, vascularisation, myomètre, col, ovaires, conduite proposée."}]},{"t":"Adénocarcinome de l'endomètre","n":"Adénocarcinome de l'endomètre et classification FIGO","u":"endometre-col/adenocarcinome-endometre.html","c":"Endomètre et col","b":"le diagnostic est histologique (biopsie sous hystéroscopie). L'IRM sert au bilan d'extension ; son enjeu principal est de dire si la tumeur envahit plus ou moins de la moitié du myomètre.","s":[{"i":"terrain","t":"Terrain","x":"Fréquent : deuxième cancer gynécologique après le cancer du sein. Clinique : métrorragies post-ménopausiques. Facteurs de risque : obésité, diabète, hyperœstrogénie (nulligestité, traitement hormonal substitutif, Tamoxifène, SOPK), syndrome de Lynch (HNPCC)."},{"i":"anatomopathologie","t":"Anatomopathologie","x":"Type · Histologie · Comportement Type I (85 à 90 %) · Endométrioïde grades 1 et 2 · Lent, hormono-dépendant Type II (10 à 15 %) · Endométrioïde grade 3, cellules claires, séreux papillaire, carcinosarcome · Agressif Cette opposition type I / type II est aujourd'hui remplacée par le type histologique (agressif ou non, voir FIGO 2023) et par quatre groupes moléculaires : POLE muté (pronostic excellent), déficience du système MMR (dMMR, à rapprocher du syndrome de Lynch), p53 anormal (pronostic défavorable) et sans profil moléculaire spécifique (NSMP)."},{"i":"imagerie","t":"Imagerie","x":"Masse endométriale Masse tissulaire endocavitaire en signal T2 intermédiaire, sans microkyste. Hypersignal diffusion avec ADC bas (< 1,15 × 10⁻³ mm²/s). Rehaussement inférieur au myomètre ; hétérogène, ± nécrose ; distension utérine si volumineuse. Envahissement du myomètre Interface endomètre-myomètre irrégulière, interruption de la zone jonctionnelle. Mesure : épaisseur de myomètre sain restant en regard de l'infiltration la plus profonde, rapportée à l'épaisseur totale du myomètre (seuil de 50 %). La tumeur, peu rehaussée, se détache bien du myomètre au temps tardif. Séquences clés T2 en coupes fines, obliques perpendiculaires au corps utérin. Diffusion focalisée perpendiculaire au corps utérin. T1 3D après gadolinium au temps tardif (2 min 30)."},{"i":"classification-figo-2023","t":"Classification FIGO 2023","x":"La FIGO 2023 garde les quatre grandes étapes anatomiques : I, utérus ; II, col ; III, extension locorégionale ; IV, vessie, rectum ou à distance. Elle ajoute trois données que seule l'histologie fournit : le type histologique (agressif ou non), les emboles lymphovasculaires et, quand elle est disponible, la classification moléculaire. L'IRM décrit l'extension anatomique. Le stade définitif est fixé après l'analyse anatomopathologique. Définitions utiles Types non agressifs : carcinome endométrioïde de bas grade (grades 1 et 2). Types agressifs : endométrioïde de haut grade (grade 3), séreux, à cellules claires, indifférencié, mixte, mésonéphrique-like, mucineux de type gastro-intestinal, carcinosarcome. Emboles lymphovasculaires étendus : au moins 5 vaisseaux envahis. Les emboles absents ou focaux ne modifient pas le stade. Stade · Définition · Traduction en imagerie IA1 · Type non agressif limité à un polype ou à l'endomètre · Zone jonctionnelle respectée IA2 · Type non agressif, envahissement < 50 % du myomètre, emboles absents ou focaux · Envahissement myométrial < 50 % IA3 · Endométrioïde de bas grade limité à l'utérus et à un ovaire (critères ci-dessous) · Masse ovarienne unilatérale associée IB · Type non agressif, envahissement ≥ 50 % du myomètre, emboles absents ou focaux · Envahissement myométrial ≥ 50 % IC · Type agressif limité à un polype ou à l'endomètre · Zone jonctionnelle respectée IIA · Envahissement du stroma cervical, type non agressif · Interruption de l'anneau stromal cervical en hyposignal T2 IIB · Emboles lymphovasculaires étendus, type non agressif · Non visible en imagerie IIC · Type agressif avec envahissement du myomètre, quelle qu'en soit la profondeur · Tout envahissement myométrial IIIA1 · Ovaire ou trompe (hors critères IA3) · Masse annexielle IIIA2 · Sous-séreuse utérine ou franchissement de la séreuse · Interruption du liseré myométrial externe, contour utérin irrégulier IIIB1 · Vagin et/ou paramètres · Interruption de la paroi vaginale en hyposignal T2, infiltration de la graisse paramétriale IIIB2 · Péritoine pelvien · Nodules ou épaississement péritonéal pelvien IIIC1 · Ganglions pelviens : i, micrométastase ; ii, macrométastase · Ganglions pelviens suspects IIIC2 · Ganglions lombo-aortiques jusqu'aux veines rénales, avec ou sans ganglions pelviens : i ou ii · Ganglions lombo-aortiques suspects IVA · Muqueuse vésicale et/ou digestive · Perte du liseré en hyposignal T2 de la paroi vésicale ou rectale, bourgeon muqueux IVB · Péritoine abdominal au-delà du pelvis · Carcinose péritonéale abdominale IVC · Métastases à distance, y compris ganglions au-dessus des veines rénales, poumon, foie, cerveau, os · Bilan d'extension TDM thoraco-abdomino-pelvien Critères du stade IA3 (tous requis) : envahissement < 50 % du myomètre ; pas d'emboles lymphovasculaires étendus ; pas d'autre métastase ; tumeur ovarienne unilatérale, limitée à l'ovaire, sans effraction capsulaire ni rupture. Ganglions : macrométastase > 2 mm ; micrométastase de 0,2 à 2 mm (et/ou > 200 cellules), comptée comme envahissement ; cellules tumorales isolées ≤ 0,2 mm, notées pN0(i+) sans changer le stade. Classification moléculaire (stades I et II, quand elle est connue) POLE muté : stade IAm POLEmut, quels que soient le type histologique et les emboles, tant que la tumeur reste limitée au corps ou au col. Pronostic excellent. p53 anormal avec envahissement du myomètre : stade IICm p53abn, avec ou sans atteinte du col, quels que soient le type histologique et les emboles. Déficience du système MMR (dMMR) et sans profil moléculaire spécifique (NSMP) : le stade n'est pas modifié ; le sous-type est mentionné. Pour le radiologue : les items à décrire ne changent pas. Seuil de 50 % du myomètre, stroma cervical, séreuse, annexes, vagin et paramètres, péritoine pelvien et abdominal, ganglions pelviens, lombo-aortiques et au-dessus des veines rénales. L'atteinte isolée des glandes endocervicales, sans envahissement du stroma, ne fait pas passer au stade II. Le stade proposé en IRM reste un stade d'imagerie, à compléter par l'histologie."},{"i":"facteurs-pronostiques-et-prise-en-charge-stade-i","t":"Facteurs pronostiques et prise en charge (stade I)","x":"Quatre facteurs histopronostiques : stade FIGO, type histologique, grade, emboles lymphatiques. Groupe · Critères · Chirurgie Faible risque · Type I grade 1–2, envahissement < 50 % · Hystérectomie totale + annexectomie bilatérale Risque intermédiaire · Type I grade 1–2 et envahissement ≥ 50 %, ou type I grade 3 et envahissement < 50 % · Idem + ganglion sentinelle Haut risque · Type I grade 3 et envahissement ≥ 50 %, type II, ou emboles lymphatiques · Idem + curage pelvien et lombo-aortique"},{"i":"pieges","t":"Pièges","x":"L'adénomyose, un myomètre aminci aux cornes ou un utérus distendu peuvent faire sur- ou sous-estimer l'envahissement. Un polype ou un caillot ne doivent pas être pris pour la tumeur."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille de la tumeur, envahissement du myomètre (< ou ≥ 50 %), stroma cervical, séreuse, annexes, vagin, paramètres, péritoine, ganglions pelviens, lombo-aortiques et au-dessus des veines rénales, stade FIGO 2023 d'imagerie."}]},{"t":"Sarcomes endométriaux","n":"Sarcomes endométriaux","u":"endometre-col/sarcomes-endometriaux.html","c":"Endomètre et col","b":"volumineuse masse endométriale hétérogène qui distend l'utérus, avec nécrose et forte restriction de diffusion. Le rôle du radiologue est de suspecter un sarcome, pas d'en préciser le type.","s":[{"i":"definition","t":"Définition","x":"Tumeurs malignes primitives de l'utérus d'origine non épithéliale ou mixte ; rares. Trois sous-types : carcinosarcome (équivalent d'un cancer de type II), sarcome du stroma endométrial, adénosarcome."},{"i":"imagerie-irm-examen-de-reference","t":"Imagerie (IRM, examen de référence)","x":"Masse endométriale en signal T2 intermédiaire. Restriction importante de la diffusion. Hétérogène : nécrose, remaniements hémorragiques. Envahissement myométrial avec interface irrégulière, distension utérine, ± adénopathies."},{"i":"carcinosarcome","t":"Carcinosarcome","x":"Tumeur maligne mixte : composante épithéliale carcinomateuse et composante sarcomateuse de haut grade. Moins de 5 % des tumeurs utérines ; deuxième sarcome utérin en fréquence. Femme ménopausée ; saignements, masse pelvienne. Très agressif : atteinte extra-utérine d'emblée dans 30 à 40 % des cas (ganglions, poumons), récidive dans plus de 50 % des cas. Imagerie : masse hétérogène « soufflante », souvent étendue au canal endocervical, nécrose, hypersignal diffusion."},{"i":"sarcome-du-stroma-endometrial","t":"Sarcome du stroma endométrial","x":"Tumeur maligne non épithéliale ; troisième sarcome utérin en fréquence. Deux formes : bas grade et haut grade (sarcome endométrial indifférencié). Terrain : après la ménopause, hyperœstrogénie (récepteurs hormonaux positifs), ± antécédent d'irradiation pelvienne. Imagerie : distension utérine, masse avec des bandes en hyposignal T2 (faisceaux de myomètre préservés), nécrose ; extension possible le long des vaisseaux et des ligaments."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Adénocarcinome de l'endomètre volumineux. Léiomyosarcome (développé dans le myomètre). Myome sous-muqueux remanié."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, origine (endomètre ou myomètre), nécrose, diffusion, envahissement du myomètre et du col, extension extra-utérine, ganglions, métastases (scanner thoracique)."}]},{"t":"Rétention trophoblastique","n":"Rétention trophoblastique","u":"endometre-col/retention-trophoblastique.html","c":"Endomètre et col","b":"après une fausse couche ou une IVG, une masse endo-myométriale échogène et vascularisée avec des hCG qui persistent évoque une rétention. Des vitesses très élevées et des hCG très hautes orientent plutôt vers une tumeur trophoblastique.","s":[{"i":"definition","t":"Définition","x":"Persistance de tissu trophoblastique dans la cavité utérine après un arrêt de grossesse (fausse couche, IVG)."},{"i":"clinique","t":"Clinique","x":"Saignements persistants, élévation persistante des hCG."},{"i":"imagerie","t":"Imagerie","x":"Échographie avec Doppler couleur : examen de référence. Masse échogène hétérogène, endo-myométriale. Hypervascularisée au Doppler couleur, avec aliasing ; index de résistance bas (< 0,5) ; vitesse systolique maximale de l'ordre de 10 à 50 cm/s (en moyenne 40 cm/s)."},{"i":"diagnostic-differentiel","t":"Diagnostic différentiel","x":"Diagnostic · Vitesse systolique maximale · hCG Rétention trophoblastique · 10 à 50 cm/s · Peu élevées Tumeur trophoblastique gestationnelle avec malformation artério-veineuse · > 1 m/s · Très élevées Caillots : non vascularisés."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Curetage ou endo-aspiration."},{"i":"pieges","t":"Pièges","x":"Ne pas proposer de curetage à l'aveugle devant une vascularisation très intense avec des vitesses très élevées: risque hémorragique (malformation artério-veineuse)."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille de la masse, vascularisation, vitesse systolique maximale, index de résistance, épaisseur du myomètre en regard."}]},{"t":"Cancer du col utérin","n":"Cancer du col utérin et classification FIGO","u":"endometre-col/cancer-col-uterin.html","c":"Endomètre et col","b":"masse cervicale en signal T2 intermédiaire qui efface l'anneau fibreux en hyposignal T2. L'enjeu de l'IRM est l'atteinte des paramètres : un liseré d'anneau fibreux préservé autour de la tumeur l'élimine.","s":[{"i":"terrain","t":"Terrain","x":"Troisième cancer dans le monde, première cause de décès par cancer chez la femme de moins de 35 ans. Carcinome épidermoïde (85 %), adénocarcinome. Facteur de risque : infection par un papillomavirus (HPV) oncogène."},{"i":"depistage","t":"Dépistage","x":"De 25 à 30 ans : deux frottis à un an d'intervalle, puis tous les 3 ans s'ils sont normaux. De 30 à 65 ans : test HPV, frottis si le test est positif, nouveau test à 5 ans s'il est négatif."},{"i":"col-normal-en-t2-trois-couches","t":"Col normal en T2 : trois couches","x":"Interne : muqueuse du canal endocervical, en hypersignal. Intermédiaire : anneau fibreux (stroma interne), en hyposignal franc. Externe : stroma externe, en signal intermédiaire."},{"i":"imagerie-de-la-tumeur","t":"Imagerie de la tumeur","x":"Masse tissulaire cervicale en signal T2 intermédiaire, qui interrompt le hyposignal de l'anneau fibreux. Hypersignal diffusion. Rehaussement intense et précoce, supérieur au myomètre (injection dynamique). Adénopathies suspectes : > 1 cm, nécrotiques, irrégulières ou rondes (iliaques internes et externes, obturatrices, lombo-aortiques)."},{"i":"atteinte-des-parametres","t":"Atteinte des paramètres","x":"Aspect · Interprétation Anneau fibreux intact, ou liseré résiduel autour de la tumeur · Pas d'atteinte paramétriale Interruption complète + digitations tumorales dans le paramètre · Atteinte paramétriale Interruption complète + hydronéphrose · Atteinte paramétriale et urétérale Séquences clés : T2 en coupes fines (3 mm) obliques perpendiculaires au col ; diffusion focalisée perpendiculaire au col."},{"i":"classification-figo-2018","t":"Classification FIGO 2018","x":"C'est la classification en vigueur. Elle autorise l'imagerie et l'histologie à modifier le stade clinique. La source est indiquée par un suffixe : r pour l'imagerie, p pour l'histologie (par exemple IIIC1r). En cas de doute entre deux stades, on retient le stade le plus bas. Stade · Définition · Traduction en IRM IA1 · Carcinome microscopique, invasion stromale < 3 mm en profondeur · Habituellement invisible IA2 · Invasion stromale ≥ 3 mm et < 5 mm · Habituellement invisible IB1 · Invasion ≥ 5 mm, tumeur < 2 cm · Tumeur limitée au col, liseré d'anneau fibreux préservé IB2 · Tumeur ≥ 2 cm et < 4 cm · Idem, mesure du plus grand diamètre dans les 3 plans IB3 · Tumeur ≥ 4 cm · Idem IIA1 · Deux tiers supérieurs du vagin, sans atteinte paramétriale, tumeur < 4 cm · Interruption de l'hyposignal T2 de la paroi vaginale, cul-de-sac ou tiers supérieur IIA2 · Idem, tumeur ≥ 4 cm · Idem IIB · Paramètres, sans atteinte de la paroi pelvienne · Interruption complète de l'anneau fibreux, digitations ou masse dans la graisse paramétriale IIIA · Tiers inférieur du vagin, sans atteinte de la paroi pelvienne · Tumeur atteignant le tiers inférieur du vagin IIIB · Paroi pelvienne et/ou hydronéphrose ou rein muet · Tumeur au contact (ou à moins de 3 mm) des muscles obturateur interne, élévateur de l'anus, piriforme ou des vaisseaux iliaques ; dilatation urétérale IIIC1 · Ganglions pelviens, quelles que soient la taille de la tumeur et son extension (r ou p) · Ganglions iliaques ou obturateurs suspects IIIC2 · Ganglions lombo-aortiques (r ou p) · Ganglions lombo-aortiques suspects IVA · Muqueuse vésicale ou rectale, confirmée par biopsie · Perte du liseré en hyposignal T2 de la paroi, bourgeon muqueux ; l'œdème bulleux seul ne suffit pas IVB · Métastases à distance · Bilan TDM ou TEP-TDM À retenir : depuis 2018, le diamètre tumoral mesuré en IRM distingue trois sous-stades IB (2 et 4 cm) et l'envahissement ganglionnaire suffit à classer la tumeur en stade IIIC, même si elle est petite."},{"i":"pieges","t":"Pièges","x":"Un œdème ou une inflammation péritumorale après conisation peuvent faire surestimer la taille ; la diffusion aide. L'hydronéphrose classe la tumeur en stade III : toujours regarder les reins."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille dans les 3 plans, extension au corps utérin et au vagin (tiers supérieur, moyen, inférieur), paramètres (côté), paroi pelvienne, uretères, vessie, rectum, ganglions pelviens et lombo-aortiques, reins, stade FIGO 2018 d'imagerie (suffixe r)."}]},{"t":"Radio-anatomie de l'utérus et du myomètre","n":"Radio-anatomie de l'utérus et du myomètre","u":"myometre/radio-anatomie-uterus.html","c":"Myomètre","b":"en T2, le myomètre interne forme la zone jonctionnelle en franc hyposignal, le myomètre externe est en signal intermédiaire. Cette anatomie zonale est la base du diagnostic d'adénomyose et du bilan des cancers de l'endomètre.","s":[{"i":"l-uterus","t":"L'utérus","x":"Organe de la gestation, situé dans l'espace sous-péritonéal, fait de trois parties : corps, isthme et col. Trois positions en pratique : antéversé antéfléchi, position intermédiaire, rétroversé rétrofléchi. Antéversion : angle entre l'axe du corps et l'axe ombilico-coccygien ; antéflexion : angle entre l'axe du corps et l'axe du col (environ 130°)."},{"i":"le-myometre","t":"Le myomètre","x":"Trois couches de fibres musculaires lisses d'orientations différentes ; seule la distinction myomètre interne / externe est visible en imagerie. Échographie : myomètre échogène homogène ; le myomètre interne peut apparaître comme une fine bande hypoéchogène sous l'endomètre. IRM (T2) : zone jonctionnelle (myomètre interne) en franc hyposignal T2, responsable du péristaltisme utérin ; myomètre externe en signal intermédiaire."},{"i":"variations-de-la-zone-jonctionnelle","t":"Variations de la zone jonctionnelle","x":"Selon la période du cycle : épaississement transitoire pendant les règles. Selon l'imprégnation œstrogénique : mal visible avant la puberté, après la ménopause et sous pilule. Des contractions myométriales transitoires peuvent simuler un épaississement focal ou un myome : elles changent d'aspect entre deux séquences."},{"i":"pieges","t":"Pièges","x":"Éviter la période menstruelle pour mesurer la zone jonctionnelle. Une contraction ne doit pas être prise pour un myome ou une adénomyose focale : comparer les séquences T2 acquises à des moments différents."}]},{"t":"Léiomyome utérin","n":"Léiomyome utérin","u":"myometre/leiomyome-uterin.html","c":"Myomètre","b":"masse myométriale ronde et bien limitée, hypoéchogène avec une vascularisation périphérique en encorbellement, en hyposignal T2 lorsqu'elle est hyaline. Les remaniements changent le signal mais pas la bénignité.","s":[{"i":"definition","t":"Définition","x":"Prolifération tumorale bénigne de cellules musculaires lisses du myomètre. Multiples dans 98 % des cas, de taille variable."},{"i":"terrain-et-clinique","t":"Terrain et clinique","x":"Très fréquent : 20 % des femmes de plus de 30 ans. Saignements, pesanteur ou douleurs pelviennes, infertilité ; souvent asymptomatique. Complications aiguës douloureuses : nécrose aseptique (nécrobiose, pendant la grossesse ou sous progestatifs), torsion d'un myome sous-séreux pédiculé. Traitement seulement s'il est symptomatique."},{"i":"classification-des-pathologies-musculaires-lisses-oms","t":"Classification des pathologies musculaires lisses (OMS)","x":"Développement utérin · Développement extra-utérin Léiomyomes banals et remaniés ; sous-types spécifiques de léiomyomes ; tumeurs musculaires lisses de potentiel de malignité incertain (STUMP) ; léiomyosarcome ; léiomyomatose diffuse · Léiomyomatose intraveineuse ; léiomyomatose péritonéale disséminée ; léiomyome parasite ; léiomyomatose métastasiante bénigne"},{"i":"imagerie","t":"Imagerie","x":"Utérus augmenté de volume aux contours bosselés ; masses rondes ou polylobées, bien limitées, généralement multiples. Échographie : souvent hypoéchogène, cônes d'ombre en éventail, vascularisation annulaire périphérique (encorbellement). IRM : masse arrondie bien limitée, en hyposignal T2 et isosignal T1 (fibrose hyaline, remaniement le plus fréquent) ; rehaussement de type 2, parallèle au myomètre. Signe de la griffe : le myomètre s'étire autour de la masse, preuve de son origine utérine ; un myome sous-séreux pédiculé est relié à l'utérus par des vaisseaux (« vaisseaux en pont »)."},{"i":"remaniements","t":"Remaniements","x":"Remaniement · T2 · T1 · Diffusion · ADC (× 10⁻³ mm²/s) Hyalin · Hyposignal · Isosignal · Hyposignal · — Œdème · Intermédiaire · Isosignal · Hypersignal · > 1,2 Kystique · Hypersignal · Hyposignal · Hypersignal · > 2 Hémorragique (nécrobiose) · Variable, liseré périphérique · Hypersignal · — · — Calcifié · ± hyposignal · ± hyposignal · — · — Remaniement ≠ sous-type histologique : le remaniement (hyalin, œdémateux, kystique, hémorragique, calcifié) concerne un myome banal ; les sous-types histologiques (cellulaire, myxoïde, mitotiquement actif, épithélioïde, à cellules bizarres) sont des entités distinctes. Le myome cellulaire est en signal T2 intermédiaire et en hypersignal diffusion, ce qui peut inquiéter."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Fibrome ovarien : hyposignal T2, hyposignal diffusion, rehaussement de type 1, séparé de l'utérus. Adénomyome : mal limité, microkystique, sans vascularisation annulaire. Utérus pseudo-unicorne : corne rudimentaire avec une muqueuse endométriale. Adénomyose interne : utérus globuleux aux contours lisses. Contraction myométriale transitoire."},{"i":"criteres-chirurgicaux-utiles-au-compte-rendu","t":"Critères chirurgicaux utiles au compte rendu","x":"Situation · Critères Myome sous-muqueux : résection hystéroscopique déconseillée si · Taille > 5 cm ; liseré de sécurité myométrial < 5 mm ; plus de 5 myomes ; myome interstitiel accolé ; adénomyose interne profonde associée Myome interstitiel ou sous-séreux : résection cœlioscopique possible si · Diamètre < 8 cm ; moins de 3 myomes"},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille de l'utérus, nombre de myomes, et pour les principaux : taille, siège, type FIGO, liseré de myomètre sain vers la séreuse, remaniements, signal T2 ; adénomyose associée ; ovaires."}]},{"t":"Classification FIGO des myomes","n":"Classification FIGO des myomes","u":"myometre/classification-figo-myomes.html","c":"Myomètre","b":"la classification FIGO situe chaque myome de 0 (intracavitaire pédiculé) à 7 (sous-séreux pédiculé) selon sa part dans la cavité, dans le myomètre et sous la séreuse. Elle guide le choix entre hystéroscopie, cœlioscopie ou autre traitement.","s":[{"i":"types","t":"Types","x":"Type · Position · Description 0 · Sous-muqueux · Pédiculé, intracavitaire 1 · Sous-muqueux · Moins de 50 % dans le myomètre 2 · Sous-muqueux · 50 % ou plus dans le myomètre 3 · Interstitiel · Entièrement intramural, au contact de l'endomètre 4 · Interstitiel · Entièrement intramural, sans contact avec l'endomètre ni la séreuse 5 · Sous-séreux · 50 % ou plus dans le myomètre 6 · Sous-séreux · Moins de 50 % dans le myomètre 7 · Sous-séreux · Pédiculé 8 · Autre · Cervical, parasite, autres localisations Un myome qui touche à la fois l'endomètre et la séreuse est noté avec deux chiffres, le premier pour la composante sous-muqueuse (par exemple 2-5)."},{"i":"en-pratique","t":"En pratique","x":"Types 0, 1 et 2 : myomes sous-muqueux, accessibles à l'hystéroscopie selon leur taille et le liseré de myomètre sain (voir la fiche Léiomyome utérin). Types 5, 6 et 7 : abord cœlioscopique. Type 7 : risque de torsion ; diagnostic différentiel avec une masse ovarienne solide."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Pour chaque myome principal : type FIGO, taille, paroi (antérieure, postérieure, fundique, latérale), liseré de myomètre sain vers la séreuse pour les types 1 et 2."}]},{"t":"Léiomyosarcome utérin","n":"Léiomyosarcome utérin","u":"myometre/leiomyosarcome-uterin.html","c":"Myomètre","b":"rare, on le suspecte sur un faisceau d'arguments. Une masse en hyposignal T2 ou en hyposignal diffusion est bénigne ; une masse unique, volumineuse, en signal T2 intermédiaire, nécrosée et à ADC bas chez une femme de plus de 45 ans est suspecte.","s":[{"i":"definition","t":"Définition","x":"Prolifération maligne des cellules musculaires lisses du myomètre."},{"i":"terrain-et-clinique","t":"Terrain et clinique","x":"Rare : 1,3 % des tumeurs malignes de l'utérus ; plus fréquent après la ménopause. Saignements, douleurs pelviennes, masse pelvienne ; croissance rapide d'un « myome » après la ménopause."},{"i":"criteres-cliniques-et-morphologiques","t":"Critères cliniques et morphologiques","x":"Âge > 45 ans. Taille > 10 cm. Masse unique. Signal T2 intermédiaire. Localisation interstitielle. Nécrose centrale. Plage hémorragique (hypersignal T1). Contours irréguliers. Trois critères ou plus : valeur prédictive positive très élevée."},{"i":"criteres-fonctionnels-adc-10-mm-s","t":"Critères fonctionnels (ADC, × 10⁻³ mm²/s)","x":"ADC > 1,23: forte valeur prédictive négative. ADC < 1,05: forte valeur prédictive positive. Il n'existe pas de seuil d'ADC formel pour distinguer un myome cellulaire d'un léiomyosarcome."},{"i":"demarche","t":"Démarche","x":"La masse est-elle d'origine utérine ? Carcinose ou adénopathies associées = suspect. Hyposignal T2, ou signal en diffusion inférieur à celui de l'endomètre ou des ganglions = bénin. Sinon : ADC bas et/ou critères morphologiques suspects = suspect ; sinon bénin."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Myome cellulaire, myome remanié (nécrobiose, œdème) : ADC plus élevé, contours réguliers. STUMP (tumeur musculaire lisse de potentiel de malignité incertain). Sarcome du stroma endométrial, carcinosarcome : origine endométriale."},{"i":"pieges","t":"Pièges","x":"Un myome en nécrobiose est hétérogène et en hypersignal T1, mais garde des contours réguliers et ne se rehausse pas au centre. La morcellation d'un léiomyosarcome méconnu dissémine la tumeur : signaler toute masse suspecte avant une chirurgie conservatrice."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille, nombre, signal T2, diffusion et ADC, nécrose, hémorragie, contours, ganglions, carcinose, métastases (scanner thoracique)."}]},{"t":"Pathologie musculaire lisse apparentée et léiomyomatose intraveineuse","n":"Pathologie musculaire lisse apparentée et léiomyomatose intraveineuse","u":"myometre/leiomyomatoses.html","c":"Myomètre","b":"lésions léiomyomateuses rares, de croissance inhabituelle, presque toujours bénignes. La léiomyomatose intraveineuse se reconnaît à des extensions vermiculaires dans les veines, qui peuvent remonter jusqu'au cœur droit.","s":[{"i":"pathologie-musculaire-lisse-apparentee","t":"Pathologie musculaire lisse apparentée","x":"Lésions léiomyomateuses de croissance inhabituelle, en règle bénignes ; elles peuvent présenter tous les remaniements et sous-types des myomes, et exceptionnellement une composante maligne. Entité · Description Léiomyomatose utérine diffuse · Innombrables petits myomes qui remplacent le myomètre Léiomyomatose métastasiante bénigne · Nodules musculaires lisses bénins à distance, pulmonaires surtout Léiomyomatose péritonéale disséminée · Multiples nodules péritonéaux qui simulent une carcinose Léiomyome parasite · Myome détaché de l'utérus, vascularisé par une autre structure, parfois après morcellation"},{"i":"leiomyomatose-intraveineuse","t":"Léiomyomatose intraveineuse","x":"Définition : prolifération de tissu musculaire lisse, classiquement bénin, dans les veines myométriales ou pelviennes. Utérus augmenté de volume aux limites irrégulières, avec des extensions tubulées vermiculaires dans les veines paramétriales, utérines, hypogastriques. Signal T2 et diffusion variables selon les remaniements, le sous-type ou une éventuelle composante sarcomateuse. Extension possible aux veines iliaques, à la veine cave inférieure, aux cavités cardiaques droites et aux artères pulmonaires. Complications : embolies tumorales et/ou cruoriques."},{"i":"pieges","t":"Pièges","x":"Une léiomyomatose péritonéale disséminée ressemble à une carcinose : le signal des nodules, proche de celui des myomes, oriente. Devant un utérus polymyomateux avec des structures tubulées paramétriales, suivre les veines jusqu'à la veine cave."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Extension veineuse (niveau le plus haut atteint : iliaque, cave, oreillette droite), thrombose associée, nodules pulmonaires ou péritonéaux."}]},{"t":"Adénomyose interne","n":"Adénomyose interne","u":"myometre/adenomyose-interne.html","c":"Myomètre","b":"invagination de l'endomètre dans le myomètre. Les signes directs (glandes ectopiques) sont spécifiques, les signes indirects (hypertrophie musculaire) sont sensibles ; des signes indirects isolés ne suffisent pas pour conclure.","s":[{"i":"definition","t":"Définition","x":"Présence anormale de glandes endométriales dans le myomètre, avec une hypertrophie musculaire secondaire. Mécanisme : traumatisme de l'interface endomètre-myomètre."},{"i":"terrain-et-clinique","t":"Terrain et clinique","x":"Fréquente : 30 à 50 % des femmes. Saignements, dysménorrhées, infertilité."},{"i":"types-d-adenomyose","t":"Types d'adénomyose","x":"Type · Mécanisme · Formes Interne · Invagination de la muqueuse dans le myomètre · Superficielle ou profonde ; diffuse ou focale ; symétrique ou asymétrique Externe · Colonisation du myomètre externe de dehors en dedans depuis une endométriose profonde · Postérieure ou antérieure Adénomyome · Zone focale de fibres musculaires et d'îlots endométriaux · Plein ou kystique ; interstitiel, intracavitaire ou sous-séreux Extension de l'adénomyose interne : superficielle (tiers interne du myomètre) ou profonde (deux tiers internes ou plus) ; limitée à une paroi ou étendue à plusieurs."},{"i":"imagerie","t":"Imagerie","x":"Échographie (signes repris par les critères MUSA) Signes indirects · Signes directs Utérus volumineux, globuleux, asymétrique ; myomètre hétérogène ; vascularisation radiaire (traversante) ; interface endomètre-myomètre floue et irrégulière · Petites lacunes anéchogènes dans le myomètre ; nodules et stries linéaires hyperéchogènes juxta-endométriaux IRM Signes directs : spots en hypersignal T2 ± T1 dans le myomètre. Signes indirects : épaississement de la zone jonctionnelle > 11 mm ; rapport zone jonctionnelle / myomètre total > 40 %."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Myome : bien limité, vascularisation annulaire, cônes d'ombre, contours bosselés. Contraction myométriale transitoire : change d'aspect entre deux séquences."},{"i":"pieges","t":"Pièges","x":"Signes indirects musculaires isolés : ne pas conclure formellement à une adénomyose interne. Éviter la période menstruelle : pseudo-épaississement de la zone jonctionnelle."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Type (diffuse ou focale), profondeur (superficielle ou profonde), parois atteintes, signes directs, épaisseur maximale de la zone jonctionnelle, endométriose et adénomyose externe associées."}]},{"t":"Adénomyose externe","n":"Adénomyose externe","u":"myometre/adenomyose-externe.html","c":"Myomètre","b":"masse endométriosique du myomètre externe, en continuité avec une endométriose profonde adjacente. Elle est postérieure dans 90 % des cas.","s":[{"i":"mecanisme","t":"Mécanisme","x":"Implants péritonéaux d'endométriose qui pénètrent secondairement en profondeur dans le myomètre externe, postérieur (90 %) ou antérieur (10 %)."},{"i":"imagerie","t":"Imagerie","x":"Échographie : hypertrophie hétérogène du myomètre antérieur ou postérieur, ± microkystique ; utérus en « point d'interrogation » (fond utérin attiré en arrière par les adhérences). IRM : plage mal limitée du myomètre externe en hyposignal T2, ± implants en hypersignal T2 ou T1. Toujours associée à une endométriose profonde de voisinage : torus, recto-sigmoïde, symphyse du Douglas en arrière ; vessie en avant."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Myome sous-séreux : bien limité, vascularisation annulaire. Adénomyose interne : atteinte à partir de l'endomètre, zone jonctionnelle épaissie."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Paroi atteinte, épaisseur, rapport avec la zone jonctionnelle, endométriose profonde associée (recto-sigmoïde, vessie, torus)."}]},{"t":"Adénomyome","n":"Adénomyome","u":"myometre/adenomyome.html","c":"Myomètre","b":"plage focale pseudo-tumorale du myomètre, mal limitée, microkystique, sans vascularisation annulaire. C'est ce qui la distingue d'un myome.","s":[{"i":"definition","t":"Définition","x":"Zone focale de fibres musculaires lisses et d'îlots endométriaux, par réactivation de résidus müllériens ectopiques. Terrain : femme jeune, ± antécédent de geste endo-utérin."},{"i":"formes","t":"Formes","x":"Plein ou kystisé. Interstitiel, intracavitaire (polypoïde) ou sous-séreux."},{"i":"imagerie","t":"Imagerie","x":"Adénomyome plein Plage pseudo-tumorale mal limitée, d'aspect « léiomyomateux », ± adénomyose interne associée. Échographie : plage mal limitée avec microkystes, sans vascularisation périphérique annulaire. IRM : plage nodulaire mal limitée en hyposignal T2, avec des spots en hypersignal T2 ± T1. Adénomyome kystique Formation arrondie kystique à contenu hémorragique de signal endométriosique, entourée d'une couronne en hyposignal T2. Adénomyome polypoïde Lésion endocavitaire de signal T2 variable, avec spots en hypersignal T2 ± T1, ± adénomyose interne."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Critère · Adénomyome · Myome Limites · Floues · Nettes Microkystes, spots T1 · Oui · Non Vascularisation · Pas d'encorbellement · Annulaire en encorbellement Effet de masse sur l'endomètre · Faible · Marqué Adénomyome polypoïde : polype endométrial, myome FIGO 0."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Siège, taille, forme (pleine, kystique, polypoïde), rapport avec la cavité, adénomyose associée."}]},{"t":"Lésions kystiques du myomètre","n":"Lésions kystiques du myomètre","u":"myometre/lesions-kystiques-myometre.html","c":"Myomètre","b":"le signal T1 trie les lésions kystiques du myomètre. En hyposignal T1 : myome kystique, kyste vestigial ; en hypersignal T1 : myome en nécrobiose, adénomyome kystique, masse utérine cavitaire accessoire.","s":[{"i":"orientation-selon-le-signal-t1","t":"Orientation selon le signal T1","x":"Hyposignal T1 · Hypersignal T1 Myome kystique · Myome en nécrobiose Kyste vestigial · Adénomyome kystique  · Masse utérine cavitaire accessoire Autres causes, plus rares : tumeur adénomatoïde kystique, échinococcose, hydrosalpinx intra-utérin, hydrocolpos, malformation congénitale."},{"i":"kyste-vestigial-intramyometrial","t":"Kyste vestigial intramyométrial","x":"Uni- ou pluriloculaire, signal liquidien pur (hyposignal T1, hypersignal T2), paroi fine et régulière, sans rehaussement interne."},{"i":"masse-uterine-cavitaire-accessoire","t":"Masse utérine cavitaire accessoire","x":"Généralement sous la corne utérine gauche, près de l'insertion du ligament rond. Masse kystique hémorragique de signal endométriosique, à parois épaisses vascularisées en franc hyposignal T2 (couronne de myomètre). Femme jeune avec une dysménorrhée sévère ; cavité utérine principale normale."},{"i":"pieges","t":"Pièges","x":"La masse utérine cavitaire accessoire ne doit pas être prise pour une corne rudimentaire : la cavité utérine principale est normale, sans malformation."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Siège, taille, signal T1 et T2, paroi, rapport avec la cavité utérine et la séreuse."}]},{"t":"Pathologie vasculaire du pelvis : vue d'ensemble","n":"Vue d'ensemble","u":"vasculaire/vue-ensemble.html","c":"Pathologie vasculaire","b":"anomalie artérielle = haut débit (malformation artério-veineuse, faux anévrisme) ; anomalie veineuse = bas débit (syndrome de congestion pelvienne). Le traitement est le plus souvent interventionnel.","s":[{"i":"classification","t":"Classification","x":"Type · Débit · Lésions Artériel, acquis ou congénital · Haut · Malformation artério-veineuse, faux anévrisme, anévrisme, fistule artério-veineuse Veineux · Bas · Syndrome de congestion pelvienne, malformations veineuses et lymphatiques"},{"i":"rappel-anatomique","t":"Rappel anatomique","x":"Artère iliaque commune, qui se divise en : artère iliaque externe : membres inférieurs, paroi abdominale, organes génitaux externes ; artère iliaque interne (hypogastrique) : branches postérieures pour la région fessière et la paroi du bassin, branches antérieures pour les viscères pelviens (dont l'artère utérine). Drainage veineux du pelvis par trois systèmes largement anastomosés : ilio-cave, ovarien, iliaque interne."},{"i":"a-retenir","t":"À retenir","x":"Doppler : un aliasing avec des vitesses > 1 m/s et un index de résistance bas évoquent un shunt artério-veineux ; des structures dilatées à flux lent sans aliasing évoquent des varices."}]},{"t":"Malformation artério-veineuse utérine","n":"Malformation artério-veineuse utérine","u":"vasculaire/malformation-arterio-veineuse.html","c":"Pathologie vasculaire","b":"shunt direct entre artères et veines, sans lit capillaire. Le signe pathognomonique en angio-IRM est le retour veineux précoce.","s":[{"i":"definition","t":"Définition","x":"Anomalie à haut débit par shunt entre réseau artériel et réseau veineux. Congénitale (rare) ou acquise : traumatisme utérin (IVG, curetage), tumeur trophoblastique gestationnelle (la malformation persiste dans 15 % des cas après traitement de la tumeur). Purement utérine : on parle d'anévrisme cirsoïde."},{"i":"clinique","t":"Clinique","x":"Métrorragies, parfois abondantes et brutales."},{"i":"imagerie","t":"Imagerie","x":"Échographie-Doppler Structures anéchogènes serpigineuses dans le myomètre, avec flux. Aliasing au Doppler couleur. Flux rapide : vitesse systolique maximale > 1 m/s. Faible résistance : index de résistance < 0,5. Angio-IRM (séquences dynamiques) Vides de signal (« flow voids ») : structures serpigineuses en franc hyposignal T2. Rehaussement artériel précoce de la zone, supérieur au myomètre. Retour veineux précoce, pathognomonique : opacification de la veine utérine ou ovarienne de drainage dès le temps artériel."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Rétention trophoblastique : vitesse systolique 10 à 50 cm/s, hCG peu élevées. Faux anévrisme : masse arrondie avec un collet, sans retour veineux précoce. Tumeur trophoblastique gestationnelle : masse tissulaire, hCG très élevées."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Embolisation artérielle sélective le plus souvent."},{"i":"pieges","t":"Pièges","x":"Ne jamais proposer de curetage devant une vascularisation très intense avec des vitesses > 1 m/s : risque d'hémorragie grave."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Siège et extension (utérine, extra-utérine), vitesse systolique maximale, index de résistance, artères nourricières, veines de drainage, taux d'hCG."}]},{"t":"Faux anévrisme de l'artère utérine","n":"Faux anévrisme de l'artère utérine","u":"vasculaire/faux-anevrisme.html","c":"Pathologie vasculaire","b":"masse arrondie perfusée reliée à l'artère utérine par un collet, après un traumatisme utérin. Le risque est la rupture avec une hémorragie cataclysmique.","s":[{"i":"definition","t":"Définition","x":"Sac perfusé communiquant avec la lumière artérielle, secondaire à un traumatisme de la paroi utérine (césarienne, curetage, accouchement difficile)."},{"i":"imagerie","t":"Imagerie","x":"Masse bien limitée, arrondie, intra-utérine ou para-utérine (cervicale). Échographie : masse hypoéchogène, simple ou multikystique. Doppler : remplissage uniforme, ± flux bidirectionnel alterné au collet ; vitesse systolique élevée. Angio-IRM : rehaussement artériel parallèle à celui de l'artère utérine. Signe pathognomonique : collet visible entre l'artère utérine et le pseudo-sac."},{"i":"signes-negatifs-malformation-arterio-veineuse","t":"Signes négatifs (≠ malformation artério-veineuse)","x":"Pas de structures serpigineuses (pas de vides de signal). Pas de retour veineux précoce."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Embolisation artérielle en urgence en raison du risque de rupture."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et siège du sac, artère d'origine, collet, thrombose partielle, hématome associé."}]},{"t":"Syndrome de congestion pelvienne","n":"Syndrome de congestion pelvienne","u":"vasculaire/syndrome-congestion-pelvienne.html","c":"Pathologie vasculaire","b":"douleurs pelviennes chroniques de fin de journée chez une multipare, avec des varices pelviennes et un reflux dans la veine ovarienne. Le diagnostic est d'abord clinique ; l'imagerie confirme, cherche une cause et prépare l'embolisation.","s":[{"i":"definition","t":"Définition","x":"Syndrome clinico-radiologique : augmentation du volume sanguin veineux pelvien responsable de douleurs ; pathologie veineuse à expression gynécologique."},{"i":"mecanismes","t":"Mécanismes","x":"Insuffisance valvulaire des veines gonadiques. Obstacle au drainage veineux. Hyperpression locale."},{"i":"terrain","t":"Terrain","x":"Multiparité : varices pelviennes symptomatiques chez environ 30 % des multipares (2 enfants ou plus)."},{"i":"clinique","t":"Clinique","x":"Douleurs pelviennes chroniques (plus de 6 mois), ± cycliques, déclenchées par l'orthostatisme, maximales en fin de journée, avec une sensation de pesanteur ; irradiation aux membres inférieurs. Dysménorrhées, dyspareunies, douleurs post-coïtales, dysurie inexpliquée. Varices vulvaires, périnéales, fessières ou des cuisses d'origine pelvienne. L'enjeu n'est pas de traiter les varices vues en imagerie, mais de poser les bonnes questions."},{"i":"role-de-l-imagerie","t":"Rôle de l'imagerie","x":"Éliminer les autres causes de douleurs pelviennes chroniques. Confirmer la dilatation du réseau veineux pelvien (varicose pelvienne). Chercher une cause secondaire d'obstacle au drainage. Cartographier avant embolisation."},{"i":"imagerie","t":"Imagerie","x":"Échographie : varices = structures tubulées serpigineuses anéchogènes, flux lent sans aliasing au Doppler. IRM avec séquences dynamiques : varices en hypersignal T2 qui se rehaussent ; reflux dans la veine ovarienne gauche en angio-IRM. Critères de varicose pelvienne Critère · Seuil Veines péri-utérines · > 4 mm Veines arquées myométriales · > 2 mm Veines ovariennes · > 7 mm Vitesse du flux · < 3 cm/s Reflux dans les veines ovariennes · Spontané ou provoqué (échographie, angio-IRM)"},{"i":"causes-d-obstacle-a-chercher","t":"Causes d'obstacle à chercher","x":"Syndrome du casse-noisettes (Nutcracker) : compression de la veine rénale gauche dans la pince aorto-mésentérique. Syndrome de May-Thurner (Cockett) : compression de la veine iliaque commune gauche entre l'artère iliaque commune droite et le promontoire."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Radiologie interventionnelle : embolisation des veines ovariennes et/ou iliaques internes."},{"i":"pieges","t":"Pièges","x":"Des varices pelviennes sont fréquentes chez la multipare asymptomatique : pas de diagnostic sans clinique compatible. L'examen en décubitus sous-estime la dilatation veineuse."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Calibre des veines ovariennes, péri-utérines et arquées, reflux, veine rénale gauche et veine iliaque commune gauche, autres causes de douleur."}]},{"t":"Thrombophlébite ovarienne","n":"Thrombophlébite ovarienne","u":"vasculaire/thrombophlebite-ovarienne.html","c":"Pathologie vasculaire","b":"douleur et fièvre après un accouchement, veine ovarienne droite dilatée avec un thrombus. Le scanner avec injection est l'examen de référence.","s":[{"i":"definition","t":"Définition","x":"Thrombus de la veine gonadique."},{"i":"contexte","t":"Contexte","x":"Post-partum surtout ; pathologie inflammatoire pelvienne ; chirurgie pelvienne. Clinique : douleurs (fosse iliaque ou flanc droit) et fièvre après un accouchement."},{"i":"imagerie-scanner","t":"Imagerie (scanner)","x":"Veine ovarienne droite le plus souvent (drainage direct dans la veine cave, flux du post-partum). Signes directs : veine ovarienne dilatée, contenu spontanément hyperdense, image en cible avec rehaussement annulaire de la paroi après injection. Signes indirects : utérus du post-partum, urétéro-hydronéphrose, masse annexielle. Rechercher une extension du thrombus à la veine cave inférieure ou à la veine rénale gauche, et une embolie pulmonaire."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Appendicite, pyosalpinx, abcès tubo-ovarien, endométrite du post-partum."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Anticoagulation et antibiothérapie."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Côté, étendue du thrombus, extension cave ou rénale, embolie pulmonaire si le thorax est exploré, collection associée."}]},{"t":"Malformations : embryologie et démarche","n":"Embryologie et démarche","u":"malformations/embryologie-demarche.html","c":"Malformations","b":"les canaux de Müller forment l'utérus, les trompes et les deux tiers supérieurs du vagin. Un défaut de développement, de fusion ou de résorption donne trois familles de malformations ; sauf pour l'utérus cloisonné, il faut chercher une malformation urinaire.","s":[{"i":"les-trois-phases","t":"Les trois phases","x":"Phase · Anomalie · Malformations Développement des canaux de Müller · Absence de développement · Aplasie bilatérale complète (Rokitansky) ; aplasie unilatérale (utérus unicorne) Fusion des canaux · Absence de fusion · Utérus bicorne bicervical ou unicervical Résorption de la cloison · Absence de résorption · Utérus cloisonné total ou subtotal ; fond arqué Le tiers inférieur du vagin vient du sinus urogénital, pas des canaux de Müller : il est présent dans les aplasies müllériennes. Les ovaires, d'origine différente, sont normaux dans les malformations müllériennes."},{"i":"reflexe","t":"Réflexe","x":"Malformation génitale (sauf utérus cloisonné) = chercher une malformation urinaire, en particulier une agénésie rénale."},{"i":"technique","t":"Technique","x":"Échographie 3D en coupe frontale et IRM (T2 dans un plan coronal aligné sur le grand axe de l'utérus) montrent le contour externe du fond et la cavité en même temps. Toujours explorer les reins."},{"i":"raisonner-devant-une-amenorrhee-primaire","t":"Raisonner devant une aménorrhée primaire","x":"Caractères sexuels secondaires présents et douleurs cycliques : obstacle à l'écoulement (imperforation hyménéale, cloison vaginale transverse, hématocolpos). Caractères sexuels secondaires présents sans douleur, utérus absent : syndrome de Rokitansky (ovaires normaux, caryotype XX) ou insensibilité aux androgènes (pas d'ovaire, caryotype XY)."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Contour externe du fond utérin (incisure), nombre de cavités, de cols et de vagins, cloison (étendue, nature fibreuse ou musculaire), cornes rudimentaires (fonctionnelles, communicantes), ovaires, reins, endométriose associée."}]},{"t":"Aplasie bilatérale : syndrome de Rokitansky et insensibilité aux androgènes","n":"Aplasie bilatérale : syndrome de Rokitansky et insensibilité aux androgènes","u":"malformations/rokitansky-insensibilite-androgenes.html","c":"Malformations","b":"devant une agénésie utéro-vaginale, deux diagnostics : syndrome de Rokitansky si les ovaires sont normaux et le caryotype XX ; insensibilité aux androgènes s'il n'y a pas d'ovaire normal et que le caryotype est XY.","s":[{"i":"aplasie-ou-hypoplasie-mullerienne-bilaterale","t":"Aplasie ou hypoplasie müllérienne bilatérale","x":"Défaut de développement bilatéral des canaux de Müller, parfois segmentaire (vagin, col, corps, trompe). Hypoplasie utérine : distance intercornuale < 20 mm, hauteur utérine < 50 mm."},{"i":"syndrome-de-rokitansky-mayer-rokitansky-kuster-hauser","t":"Syndrome de Rokitansky (Mayer-Rokitansky-Küster-Hauser)","x":"1 naissance féminine sur 5000. Aménorrhée primaire non douloureuse, caryotype 46,XX, caractères sexuels secondaires féminins, dosages hormonaux normaux. Imagerie : agénésie de l'utérus, des trompes et des deux tiers supérieurs du vagin ; ovaires normaux et fonctionnels, parfois en position haute. Résidus müllériens possibles : cornes rudimentaires borgnes, latéralisées, fonctionnelles ou non. Malformations rénales associées dans 25 % des cas."},{"i":"syndrome-d-insensibilite-aux-androgenes","t":"Syndrome d'insensibilité aux androgènes","x":"Phénotype féminin malgré un caryotype 46,XY : les gonades se différencient en testicules, mais les tissus ne répondent pas aux androgènes. 1 naissance masculine sur 20 000. Aménorrhée primaire non douloureuse, caractères sexuels secondaires féminins. Imagerie : agénésie de l'utérus, des trompes et des deux tiers supérieurs du vagin ; pas d'ovaire normal ; formations tissulaires ovalaires en signal T2 intermédiaire = testicules. Ectopie testiculaire fréquente (grande lèvre, canal inguinal, abdomen) : risque de cancérisation."},{"i":"comparaison","t":"Comparaison","x":"Critère · Rokitansky · Insensibilité aux androgènes Caryotype · 46,XX · 46,XY Gonades · Ovaires normaux · Testicules, souvent ectopiques Pilosité pubienne et axillaire · Normale · Rare ou absente Malformations rénales · Fréquentes · Non"},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Utérus et vagin (présence, longueur du vagin), résidus müllériens (fonctionnels ou non), gonades (aspect, position), reins."}]},{"t":"Utérus unicorne et pseudo-unicorne","n":"Utérus unicorne et pseudo-unicorne","u":"malformations/uterus-unicorne.html","c":"Malformations","b":"hémi-utérus très latéro-dévié en « flamme de bougie ». Il faut chercher une corne rudimentaire : si elle est fonctionnelle, elle expose à une grossesse ectopique et justifie une chirurgie préventive.","s":[{"i":"definition","t":"Définition","x":"Défaut de développement d'un seul canal de Müller. Complet : utérus unicorne vrai. Partiel : utérus pseudo-unicorne avec un résidu müllérien controlatéral (corne rudimentaire)."},{"i":"imagerie","t":"Imagerie","x":"Hémi-utérus très latéro-dévié, en « flamme de bougie ». Anatomie zonale conservée en T2. Longueur normale mais largeur insuffisante. Un seul ligament rond pour l'hémi-utérus. Corne rudimentaire (elle a son propre ligament rond) Communicante ou non avec l'hémi-utérus. Fonctionnelle ou non, selon la présence d'un endomètre visible. Une corne fonctionnelle non communicante peut se remplir de sang (hématométrie douloureuse)."},{"i":"organes-associes","t":"Organes associés","x":"Ovaires normaux, parfois ectopiques du côté malformé. Malformation rénale dans 30 % des cas, du côté opposé à l'hémi-utérus (côté de la corne)."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Corne rudimentaire fonctionnelle : risque de grossesse ectopique dans la corne (à évoquer devant des douleurs) ; chirurgie préventive indiquée."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Myome sous-séreux latéral : pas d'endomètre, vascularisation annulaire. Masse utérine cavitaire accessoire : cavité utérine principale normale."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Côté de l'hémi-utérus, corne rudimentaire (présence, endomètre fonctionnel, communication, hématométrie), ovaires, reins, endométriose associée."}]},{"t":"Utérus bicorne et anomalies de fusion","n":"Utérus bicorne et anomalies de fusion","u":"malformations/uterus-bicorne.html","c":"Malformations","b":"deux cornes utérines séparées par une incisure externe du fond > 1 cm. Un hémi-vagin borgne s'accompagne toujours d'une agénésie rénale du même côté.","s":[{"i":"definition","t":"Définition","x":"Défaut de fusion, complet ou partiel, des canaux de Müller. Incisure externe fundique > 1 cm ; variantes selon le degré du défaut : ± deux hémi-isthmes, ± deux hémi-cols, ± deux hémi-vagins."},{"i":"formes","t":"Formes","x":"Forme · Description Bicorne unicervical · Deux corps, un col Bicorne bicervical · Deux corps, deux cols, un vagin perméable Didelphe vrai · Deux corps, deux cols, deux vagins perméables Bicorne bicervical avec hémi-vagin borgne · Un vagin perméable, un hémi-vagin borgne"},{"i":"cas-particulier-hemi-vagin-borgne","t":"Cas particulier : hémi-vagin borgne","x":"Utérus bicorne bicervical avec un hémi-vagin borgne (syndrome de Herlyn-Werner-Wunderlich). Hématocolpos et hématométrie du côté borgne, douloureux à la puberté alors que les règles s'écoulent par l'autre côté. Agénésie rénale systématique du côté de l'hémi-vagin borgne. Risque d'endométriose par reflux."},{"i":"diagnostics-differentiels-de-l-hematocolpos","t":"Diagnostics différentiels de l'hématocolpos","x":"Imperforation hyménéale. Cloison vaginale transverse."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Utérus cloisonné : fond externe plat ou incisure < 1 cm."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Profondeur de l'incisure externe, nombre de cols et de vagins, hématocolpos ou hématométrie, reins, endométriose."}]},{"t":"Utérus cloisonné et fond arqué","n":"Utérus cloisonné et fond arqué","u":"malformations/uterus-cloisonne.html","c":"Malformations","b":"massif utérin unique au fond externe plat (pas d'incisure externe > 1 cm), avec une cloison qui divise la cavité. C'est la seule malformation sans anomalie rénale associée.","s":[{"i":"definition","t":"Définition","x":"Défaut de résorption, total ou partiel, de la cloison entre les canaux de Müller fusionnés. Incisure externe fundique < 1 cm (≠ bicorne). Pas de malformation rénale : l'anomalie survient tard dans l'embryogenèse."},{"i":"imagerie","t":"Imagerie","x":"Massif utérin unique, non bifide. Cloison qui sépare le corps, l'isthme, le col, voire le vagin selon l'étendue du défaut. Cloison fibreuse (franc hyposignal T2) ou musculaire (signal du myomètre) : l'information compte pour la chirurgie hystéroscopique."},{"i":"formes","t":"Formes","x":"Cloisonné complet (total) : cloison jusqu'au col, parfois au vagin. Cloisonné subtotal : cloison corporelle et isthmique, sans cloison cervicale."},{"i":"uterus-cloisonne-ou-fond-arque","t":"Utérus cloisonné ou fond arqué ?","x":"Mesurer la profondeur de la saillie fundique dans la cavité (x) et la largeur entre les deux ostiums tubaires (y). x / y > 10 % : utérus cloisonné ; x / y < 10 % : fond arqué. Le fond arqué est plutôt une variante de la normale ; ce diagnostic est souvent posé de façon subjective devant une minime séparation de la cavité au fond."},{"i":"pieges","t":"Pièges","x":"Toujours juger le contour externe du fond : c'est lui qui distingue cloisonné et bicorne, pas la forme de la cavité."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Contour externe du fond, longueur et nature de la cloison, atteinte du col et du vagin, épaisseur du myomètre au fond."}]},{"t":"Utérus communiquant","n":"Utérus communiquant","u":"malformations/uterus-communiquant.html","c":"Malformations","b":"utérus à deux hémi-cavités qui communiquent au niveau de l'isthme ; forme rare, à connaître pour ne pas la confondre avec une malformation simple.","s":[{"i":"definition","t":"Définition","x":"Deux hémi-cavités utérines communicant au niveau de l'isthme, par un orifice."},{"i":"formes-decrites","t":"Formes décrites","x":"Utérus bicorne bicervical communiquant. Utérus cloisonné total communiquant. Utérus bicorne avec cloison cervicale communiquant."},{"i":"imagerie","t":"Imagerie","x":"IRM en T2 dans un plan coronal aligné sur l'utérus : orifice de communication isthmique entre les deux hémi-cavités."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Type de malformation sous-jacente, siège de la communication, nombre de cols et de vagins, reins."}]},{"t":"Classifications des malformations génitales","n":"Classifications des malformations","u":"malformations/classifications-malformations.html","c":"Malformations","b":"deux classifications sont utilisées. Celle de l'American Fertility Society (1988) décrit sept classes d'utérus ; celle de l'ESHRE/ESGE (2013) code séparément l'utérus (U), le col (C) et le vagin (V).","s":[{"i":"classification-de-l-american-fertility-society-1988","t":"Classification de l'American Fertility Society (1988)","x":"Classe · Malformation · Sous-types I · Hypoplasie ou agénésie · Vaginale, cervicale, fundique, tubaire, combinée II · Unicorne · Corne communicante, non communicante, sans cavité, sans corne III · Didelphe · — IV · Bicorne · Complet, partiel V · Cloisonné · Complet, partiel VI · Arqué · — VII · Lié au diséthylstilbestrol (Distilbène) · —"},{"i":"classification-eshre-esge-2013","t":"Classification ESHRE/ESGE (2013)","x":"Utérus Classe · Anomalie · Sous-classes U0 · Utérus normal · — U1 · Utérus dysmorphique · a. en T ; b. infantile ; c. autres U2 · Utérus cloisonné · a. partiel ; b. complet U3 · Utérus bicorporel · a. partiel ; b. complet ; c. bicorporel cloisonné U4 · Hémi-utérus · a. avec cavité rudimentaire (corne communicante ou non) ; b. sans cavité rudimentaire U5 · Aplasique · a. avec cavité rudimentaire ; b. sans cavité rudimentaire U6 · Malformation non classée · — Col et vagin Code · Col · Code · Vagin C0 · Col normal · V0 · Vagin normal C1 · Col cloisonné · V1 · Cloison vaginale longitudinale non obstructive C2 · Deux cols « normaux » · V2 · Cloison vaginale longitudinale obstructive C3 · Aplasie cervicale unilatérale · V3 · Cloison vaginale transverse et/ou imperforation hyménéale C4 · Aplasie cervicale · V4 · Aplasie vaginale Exemple : un utérus cloisonné complet avec col cloisonné et vagin normal se code U2b C1 V0."},{"i":"correspondances-utiles","t":"Correspondances utiles","x":"AFS · ESHRE/ESGE Unicorne (II) · Hémi-utérus (U4) Didelphe (III), bicorne (IV) · Bicorporel (U3) Cloisonné (V) · Cloisonné (U2) Agénésie (I) · Aplasique (U5) Lié au Distilbène (VII) · Dysmorphique en T (U1a)"},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Nommer la malformation en clair, puis la coder dans la classification utilisée par l'équipe."}]},{"t":"Maladie trophoblastique gestationnelle : généralités","n":"Généralités","u":"trophoblaste/generalites.html","c":"Maladie trophoblastique","b":"prolifération et maturation anormales du trophoblaste, et cancers qui en dérivent. Le diagnostic repose sur des hCG très élevées et l'échographie-Doppler.","s":[{"i":"terrain","t":"Terrain","x":"Femme en période d'activité génitale, pic entre 20 et 40 ans."},{"i":"diagnostic","t":"Diagnostic","x":"hCG quantitatives très élevées (milliers d'UI/L), sauf pour quelques types histologiques rares à faible sécrétion. Échographie-Doppler en première intention."},{"i":"classification-oms","t":"Classification OMS","x":"Lésions molaires (villosités choriales présentes) · Lésions non molaires (pas de villosités) Môle hydatiforme (80 %) : complète ou partielle · Choriocarcinome Môle invasive · Tumeur du site d'implantation placentaire  · Tumeur trophoblastique épithélioïde"},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et siège de la masse, envahissement du myomètre, vascularisation, malformation artério-veineuse, ovaires (kystes lutéiniques)."}]},{"t":"Môle hydatiforme","n":"Môle hydatiforme","u":"trophoblaste/mole-hydatiforme.html","c":"Maladie trophoblastique","b":"endomètre épaissi, échogène et microkystique « en tempête de neige », peu vascularisé, sans envahissement du myomètre, avec des hCG très élevées. L'échographie-Doppler suffit le plus souvent.","s":[{"i":"definition","t":"Définition","x":"Dégénérescence kystique bénigne du trophoblaste. Môle complète : fécondation d'un ovocyte dépourvu de matériel génétique maternel (« œuf clair ») par un seul spermatozoïde dont le génome se duplique ; pas d'embryon. Môle partielle : fécondation d'un ovocyte par deux spermatozoïdes ; présence d'un embryon non viable."},{"i":"clinique","t":"Clinique","x":"hCG très élevées (> 100 000 mUI/mL). Signes de grossesse exagérés : vomissements, métrorragies, utérus trop gros pour le terme."},{"i":"imagerie","t":"Imagerie","x":"Échographie-Doppler (examen de référence) Épaississement endométrial échogène, micro- ou macropolykystique (kystes de 1 à 30 mm), en « tempête de neige ». Pas de flux au Doppler. Kystes lutéiniques ovariens bilatéraux dans 20 % des cas. IRM (non justifiée en pratique, seulement en cas de doute) Masse strictement endométriale, à prédominance kystique (hypersignal T2). Rehaussement absent ou faible et hétérogène. Signes négatifs essentiels Pas d'envahissement du myomètre. Pas d'hypervascularisation (sauf môle partielle). Pas de malformation artério-veineuse."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Aspiration-curetage sous contrôle échographique. Surveillance des hCG jusqu'à normalisation, pour dépister une évolution vers une tumeur trophoblastique."},{"i":"diagnostics-differentiels","t":"Diagnostics différentiels","x":"Rétention trophoblastique après fausse couche : hCG moins élevées, masse vascularisée. Fausse couche avec dégénérescence hydropique du placenta."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille de la masse, présence d'un embryon, interface avec le myomètre, vascularisation, kystes lutéiniques."}]},{"t":"Tumeur trophoblastique gestationnelle","n":"Tumeur trophoblastique gestationnelle","u":"trophoblaste/tumeur-trophoblastique-gestationnelle.html","c":"Maladie trophoblastique","b":"tumeur maligne du trophoblaste, souvent après une môle, dépistée par l'évolution anormale des hCG. L'imagerie montre une double composante, tumorale (masse endo-myométriale) et vasculaire (malformation artério-veineuse).","s":[{"i":"definition","t":"Définition","x":"Tumeurs malignes dérivées du trophoblaste : molaire (môle invasive) ou non molaire (choriocarcinome surtout, tumeur du site d'implantation placentaire, tumeur trophoblastique épithélioïde)."},{"i":"circonstances-de-decouverte","t":"Circonstances de découverte","x":"Après une grossesse molaire (60 %), devant une évolution anormale des hCG. Après une grossesse normale, une IVG, une fausse couche ou une GEU."},{"i":"criteres-diagnostiques-apres-une-mole","t":"Critères diagnostiques après une môle","x":"Plateau des hCG sur au moins 4 dosages hebdomadaires successifs sur 3 semaines. Augmentation des hCG sur au moins 3 dosages hebdomadaires successifs sur 2 semaines. hCG encore détectables 6 mois après l'évacuation. Diagnostic histologique de choriocarcinome."},{"i":"imagerie","t":"Imagerie","x":"Composante tumorale Masse endo-myométriale de siège variable, hétérogène, ± kystique ou hémorragique, irrégulière et mal limitée, qui envahit le myomètre ; hypervascularisée. Composante vasculaire (malformation artério-veineuse associée) Échographie : dilatations vasculaires hypoéchogènes, aliasing au Doppler couleur, faible résistance (IR < 0,5), vitesse systolique maximale > 1 m/s. Angio-IRM : vides de signal en T1 et T2, retour veineux précoce (shunt artério-veineux). Les deux composantes évoluent de façon synchrone ou décalée ; la malformation persiste dans 15 % des cas après traitement."},{"i":"bilan-d-extension","t":"Bilan d'extension","x":"Échographie pelvienne, IRM pelvienne, scanner thoraco-abdomino-pelvien, IRM cérébrale. Métastases au diagnostic dans 30 % des cas, poumon et cerveau surtout."},{"i":"score-pronostique-figo-oms","t":"Score pronostique FIGO/OMS","x":"Facteur · 0 · 1 · 2 · 4 Âge (ans) · < 40 · ≥ 40 · — · — Grossesse précédente · Môle · Avortement · Grossesse à terme · — Intervalle grossesse-traitement (mois) · < 4 · 4 à 6 · 7 à 12 · ≥ 13 hCG avant traitement (UI/L) · < 10³ · 10³ à < 10⁴ · 10⁴ à < 10⁵ · ≥ 10⁵ Plus grande taille tumorale, utérus compris · < 3 cm · 3 à < 5 cm · ≥ 5 cm · — Sites de métastases · Poumon · Rate, rein · Tube digestif · Cerveau, foie Nombre de métastases · 0 · 1 à 4 · 5 à 8 · > 8 Chimiothérapie antérieure en échec · — · — · Monochimiothérapie · Polychimiothérapie Score ≤ 6: bas risque ; score ≥ 7: haut risque."},{"i":"conduite-a-tenir","t":"Conduite à tenir","x":"Prise en charge en centre de référence ; chimiothérapie (méthotrexate surtout). Biopsie à risque hémorragique : le traitement est souvent décidé sans preuve histologique, sur un faisceau d'arguments cliniques, biologiques et radiologiques."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Taille et siège de la masse, envahissement du myomètre et des paramètres, malformation artério-veineuse (vitesses), métastases, éléments du score."}]},{"t":"Plancher pelvien : généralités et radio-anatomie","n":"Généralités et radio-anatomie","u":"plancher-pelvien/generalites-radio-anatomie.html","c":"Plancher pelvien","b":"les dysfonctions pelvi-périnéales associent descentes d'organes (prolapsus) et troubles fonctionnels urinaires ou digestifs, surtout chez la femme ménopausée et multipare.","s":[{"i":"definition-et-terrain","t":"Définition et terrain","x":"Deux familles de symptômes : descentes d'organes = prolapsus ; troubles fonctionnels urinaires (incontinence, dysurie, pollakiurie) ou digestifs (constipation, incontinence anale, dyschésie). Terrain : femme ménopausée ; facteurs de risque principaux : âge et multiparité."},{"i":"radio-anatomie","t":"Radio-anatomie","x":"Le plancher pelvien ferme la cavité pelvienne vers le bas et soutient les organes pelviens. Il est formé d'aponévroses et des muscles releveurs de l'anus : faisceaux ilio-coccygien, pubo-viscéraux (pubo-vésical, pubo-vaginal) et pubo-rectal. Le muscle pubo-rectal forme une sangle autour de la jonction anorectale ; sa contraction ferme l'angle anorectal."},{"i":"trois-compartiments-a-analyser","t":"Trois compartiments à analyser","x":"Compartiment · Organes Antérieur (urinaire) · Vessie, urètre Moyen (gynécologique) · Utérus, col, vagin Postérieur (digestif) · Rectum, canal anal S'y ajoutent le compartiment péritonéal (cul-de-sac de Douglas) et le périnée (muscles releveurs)."}]},{"t":"Plancher pelvien : méthodes d'imagerie","n":"Méthodes d'imagerie","u":"plancher-pelvien/methodes-imagerie.html","c":"Plancher pelvien","b":"l'échographie rénale, pelvienne et périnéale est l'examen de base ; l'IRM dynamique (déféco-IRM) analyse tous les compartiments au repos et en poussée maximale.","s":[{"i":"echographie-renale-pelvienne-et-perineale","t":"Échographie rénale, pelvienne et périnéale","x":"Trois étapes : reins, vessie et pelvis, puis périnée ; mesure du résidu post-mictionnel. Échographie périnéale par voie introitale (sonde endovaginale posée sur le vestibule) : étude anatomique et fonctionnelle au repos puis en poussée ; étude des prothèses pelvi-périnéales. Structures repérées en coupe sagittale : vessie, symphyse pubienne, urètre, vagin, canal anal."},{"i":"irm-pelvienne-dynamique-defeco-irm","t":"IRM pelvienne dynamique (déféco-IRM)","x":"Indications Récidive d'un prolapsus chez une patiente opérée. Prolapsus après hystérectomie. Analyse d'une colpocèle postérieure. Discordance entre les symptômes et l'examen clinique. Bilan préopératoire. Technique Opacification rectale (environ 150 mL) et vaginale (environ 50 mL) par du gel d'échographie. Étude statique morphologique : T2 TSE dans 3 plans ou T2 3D. Étude dynamique fonctionnelle : séquences T2 rapides sagittales au repos, en poussée progressive puis maximale (répétées 3 fois), puis 3 plans en poussée maximale ; phase d'évacuation si possible. Ne pas hésiter à répéter les séquences : la fatigue musculaire démasque les prolapsus."},{"i":"interpretation","t":"Interprétation","x":"Analyse statique Organes pelviens, montages chirurgicaux, muscles et ligaments du plancher (par exemple une amyotrophie des muscles pubo-viscéraux, une béance du canal anal). Analyse dynamique : six choses à chercher Hypermobilité urétrale. Prolapsus urinaire, gynécologique ou digestif. Intussusception. Anisme. Anomalie du sphincter anal. Tonicité des muscles releveurs de l'anus. Points de repère des prolapsus : col vésical, col utérin (ou fond vaginal), cul-de-sac de Douglas, paroi antérieure du rectum, jonction anorectale."},{"i":"pieges","t":"Pièges","x":"Une poussée insuffisante sous-estime les prolapsus : vérifier l'effort en regardant la descente de la jonction anorectale et l'élargissement du hiatus."}]},{"t":"Plancher pelvien : repères et grades de sévérité","n":"Repères et grades de sévérité","u":"plancher-pelvien/reperes-grades.html","c":"Plancher pelvien","b":"trois repères suffisent en pratique : la ligne pubo-coccygienne pour les prolapsus, la ligne du canal anal pour la rectoçèle, l'angle anorectal pour la fonction sphinctérienne.","s":[{"i":"ligne-pubo-coccygienne-lpc","t":"Ligne pubo-coccygienne (LPC)","x":"Du bord inférieur de la symphyse pubienne à la dernière articulation coccygienne visible, sur une coupe sagittale médiane. Sert aux prolapsus urinaires, gynécologiques et péritonéaux : on mesure la distance perpendiculaire entre le point le plus bas de l'organe et la LPC. Prolapsus si l'organe descend de plus de 1 cm sous la LPC. Grade · Descente sous la LPC Minime · 1 à 3 cm Modéré · 3 à 6 cm Sévère · > 6 cm"},{"i":"ligne-du-canal-anal","t":"Ligne du canal anal","x":"Ligne qui passe dans la lumière du canal anal, prolongée vers le haut. Sert à la rectoçèle antérieure : on mesure la profondeur du bombement de la paroi rectale antérieure au-delà de cette ligne. Rectoçèle · Profondeur Physiologique · < 2 cm Modérée · 2 à 4 cm Sévère · > 4 cm"},{"i":"angle-anorectal","t":"Angle anorectal","x":"Angle entre l'axe du canal anal et le bord postérieur du rectum ; au repos, 85 à 95°. Il se ferme en contraction et s'ouvre en poussée ; sert à l'évaluation du dysfonctionnement sphinctérien (anisme : l'angle ne s'ouvre pas en poussée)."},{"i":"pieges","t":"Pièges","x":"Mesurer toujours sur la coupe sagittale médiane, au moment de la poussée maximale."}]},{"t":"Compartiment urinaire","n":"Compartiment urinaire","u":"plancher-pelvien/compartiment-urinaire.html","c":"Plancher pelvien","b":"on cherche une hypermobilité urétrale (horizontalisation de l'urètre de plus de 30° en poussée) et une cystocèle, en se méfiant de l'effet pelote qui masque une incontinence d'effort.","s":[{"i":"uretre","t":"Urètre","x":"Hypermobilité urétrale : horizontalisation de l'urètre de plus de 30° en poussée ; jonction vésico-urétrale qui passe sous la LPC. Effet pelote : une cystocèle s'enroule sous l'urètre et le coude, ce qui masque une incontinence urinaire d'effort ; celle-ci peut se révéler après la cure du prolapsus."},{"i":"cystocele","t":"Cystocèle","x":"Descente anormale de la vessie, qui déforme la paroi vaginale antérieure (colpocèle antérieure). Deux types : cervico-cystoptose : descente de la vessie, du col vésical et de l'urètre ; trigonoptose : descente de la base vésicale seule, typiquement après pose d'une bandelette sous-urétrale. Grade selon la descente du point le plus bas de la vessie sous la LPC (fiche Repères)."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Angle de l'urètre au repos et en poussée, position du col vésical, descente de la vessie sous la LPC et grade, type de cystocèle, résidu post-mictionnel, bandelette."}]},{"t":"Compartiment gynécologique","n":"Compartiment gynécologique","u":"plancher-pelvien/compartiment-gynecologique.html","c":"Plancher pelvien","b":"distinguer la descente utérine d'accompagnement, entraînée par une cystocèle ou une rectoçèle, de la véritable hystérocèle avec invagination vaginale ; penser à l'hypertrophie tapiroïde du col.","s":[{"i":"hysteroptose-d-accompagnement","t":"Hystéroptose d'accompagnement","x":"Descente de l'utérus et du vagin secondaire à une cystocèle ou à une rectoçèle."},{"i":"prolapsus-genital-vrai","t":"Prolapsus génital vrai","x":"Ptose de l'utérus, du col ou du vagin avec invagination vaginale : hystérocèle (utérus en place) ; trachélocèle (col restant après hystérectomie subtotale) ; invagination du fond vaginal (après hystérectomie totale). Grade selon la descente du col ou du fond vaginal sous la LPC."},{"i":"hypertrophie-tapiroide-du-col-uterin","t":"Hypertrophie tapiroïde du col utérin","x":"Allongement pathologique du col, qui peut simuler un prolapsus à l'examen clinique. Critères : lèvre antérieure du col > 25 mm ; inversion du rapport col/corps."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Position du col ou du fond vaginal au repos et en poussée, grade, hypertrophie du col, invagination vaginale, cause d'accompagnement (cystocèle, rectoçèle)."}]},{"t":"Compartiment digestif","n":"Compartiment digestif","u":"plancher-pelvien/compartiment-digestif.html","c":"Plancher pelvien","b":"un prolapsus dans l'axe du canal anal est une intussusception ; perpendiculaire à cet axe, c'est une rectoçèle. L'anisme est une contraction paradoxale du sphincter en poussée.","s":[{"i":"prolapsus-rectaux","t":"Prolapsus rectaux","x":"Type · Direction · Définition Intussusception (prolapsus rectal interne) · Dans l'axe du canal anal · Invagination de la paroi rectale dans la lumière, intra-rectale ou intra-anale, voire extra-anale (prolapsus extériorisé) Rectoçèle · Perpendiculaire à l'axe du canal anal · Bombement de la paroi rectale, généralement antérieure, vers le vagin Rectoçèle : profondeur mesurée par rapport à la ligne du canal anal ; physiologique < 2 cm, modérée 2 à 4 cm, sévère > 4 cm. Une vidange incomplète de la rectoçèle (piégeage du gel) a une valeur fonctionnelle."},{"i":"anisme","t":"Anisme","x":"Dyssynergie anorectale : contraction involontaire du sphincter strié et du muscle pubo-rectal pendant la poussée. Imagerie : l'angle anorectal ne s'ouvre pas en poussée, empreinte du muscle pubo-rectal persistante, évacuation lente et incomplète."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Rectoçèle (profondeur, vidange), intussusception (siège, extériorisation), angle anorectal au repos et en poussée, qualité de l'évacuation, position de la jonction anorectale."}]},{"t":"Compartiments péritonéal et périnéal","n":"Compartiments péritonéal et périnéal","u":"plancher-pelvien/compartiments-peritoneal-perineal.html","c":"Plancher pelvien","b":"la péritonéocèle est une descente du cul-de-sac de Douglas sous la LPC qui dissocie la cloison recto-vaginale ; le périnée descendant traduit une faiblesse des muscles releveurs.","s":[{"i":"compartiment-peritoneal-peritoneocele","t":"Compartiment péritonéal : péritonéocèle","x":"Dissection de la cloison recto-vaginale et descente de la partie déclive du péritoine sous la LPC. Contenu : toujours de la graisse (péritoine), ± structures digestives : entérocèle : anses grêles ; sigmoïdocèle : sigmoïde. Elle apparaît souvent en fin d'évacuation : poursuivre l'acquisition après la vidange rectale."},{"i":"compartiment-perineal","t":"Compartiment périnéal","x":"Descente du plancher pelvien par altération des muscles releveurs de l'anus. Périnée descendant : descente importante du plancher en poussée (jonction anorectale nettement sous la LPC). Périnée descendu : affaissement permanent des muscles releveurs, déjà visible au repos."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Profondeur de la péritonéocèle sous la LPC, contenu (graisse, grêle, sigmoïde), position de la jonction anorectale au repos et en poussée, aspect des muscles releveurs."}]},{"t":"Carcinose péritonéale : généralités et place de l'imagerie","n":"Généralités et place de l'imagerie","u":"carcinose/generalites-place-imagerie.html","c":"Carcinose péritonéale","b":"la carcinose est la dissémination péritonéale « locale » du cancer de l'ovaire. Le pronostic dépend du stade et de la qualité de la cytoréduction chirurgicale : le scanner volumique sert à la préparer.","s":[{"i":"terrain","t":"Terrain","x":"Environ 4500 cancers de l'ovaire par an en France ; âge moyen 60 ans ; 70 % diagnostiqués à un stade avancé. Carcinomes épithéliaux dans 95 % des cas, dont 70 % de carcinomes séreux de haut grade. Deux facteurs pronostiques : le stade initial et la qualité de la cytoréduction (absence de résidu tumoral visible)."},{"i":"role-du-scanner-volumique","t":"Rôle du scanner volumique","x":"Examen de référence : scanner thoraco-abdomino-pelvien injecté, coupes fines, reconstructions multiplanaires. Diagnostic positif de la carcinose. Cartographie des lésions : bilan préopératoire, recherche des contre-indications à la chirurgie, anticipation des difficultés opératoires."},{"i":"trois-etapes-d-analyse","t":"Trois étapes d'analyse","x":"Diagnostic positif : regarder les quatre localisations préférentielles (péritoine pelvien, grand omentum, gouttières pariéto-coliques, coupole diaphragmatique droite). Sans lésion dans ces quatre sites, on peut exclure une carcinose visible. Check-list complète des territoires sus- et sous-mésocoliques. Contre-indications à la chirurgie."},{"i":"rappel-classification-figo-du-cancer-de-l-ovaire-2014","t":"Rappel : classification FIGO du cancer de l'ovaire (2014)","x":"Stade · Définition I · Limité aux ovaires ou aux trompes (IA un ovaire, IB les deux, IC rupture, atteinte de surface ou cytologie positive) II · Extension pelvienne (IIA utérus ou trompes, IIB autres tissus pelviens) IIIA1 · Ganglions rétropéritonéaux envahis seuls (IIIA1i ≤ 10 mm, IIIA1ii > 10 mm) IIIA2 · Atteinte péritonéale extra-pelvienne microscopique, avec ou sans ganglions rétropéritonéaux IIIB · Implants péritonéaux extra-pelviens macroscopiques ≤ 2 cm, avec ou sans ganglions IIIC · Implants > 2 cm, avec ou sans ganglions, y compris sur la capsule du foie ou de la rate sans atteinte parenchymateuse IVA · Épanchement pleural à cytologie positive IVB · Métastases parenchymateuses et extra-abdominales, ganglions inguinaux et ganglions hors de la cavité abdominale compris"},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Ascite, localisations de la carcinose par territoire (avec la taille des plus gros implants), contre-indications chirurgicales, ganglions, atteinte pleurale, stade FIGO probable."}]},{"t":"Carcinose péritonéale : cartographie et résécabilité","n":"Cartographie et résécabilité","u":"carcinose/cartographie-resecabilite.html","c":"Carcinose péritonéale","b":"quatre localisations préférentielles à vérifier en premier, une check-list complète des territoires, puis les atteintes qui rendent la chirurgie difficile ou impossible.","s":[{"i":"quatre-localisations-preferentielles","t":"Quatre localisations préférentielles","x":"Péritoine pelvien (stade II). Grand omentum (« gâteau épiploïque » dans les formes évoluées). Gouttières pariéto-coliques. Coupole diaphragmatique droite et surface hépatique. Si aucune lésion n'est vue dans ces quatre sites, une dissémination péritonéale visible peut être exclue."},{"i":"check-list-des-territoires","t":"Check-list des territoires","x":"Étage · Territoires Sus-mésocolique · Coupoles diaphragmatiques droite et gauche, foie, ligament falciforme, pédicule hépatique, rate, estomac, petit et grand omentum, côlon transverse Sous-mésocolique · Annexes, utérus, cul-de-sac vésico-utérin, cul-de-sac de Douglas, charnière recto-sigmoïdienne, gouttières pariéto-coliques, omentum, intestin grêle, mésentère, cæcum Hors péritoine · Médiastin, plèvre, ganglions"},{"i":"localisations-non-resecables-ou-contre-indications","t":"Localisations non résécables ou contre-indications","x":"Stade IV : métastases parenchymateuses (foie, poumon), atteinte pleurale, adénomégalies médiastinales (dont le ganglion du « cardiophrénique » antérieur). Racine du mésentère (atteinte du mésentère proximal). Séreuse iléale ou séreuse gastrique étendue. Atteinte massive du hile hépatique. Atteinte de plus de 3 segments digestifs. Adénopathies sus-rénales. Ces contre-indications dépendent de l'expérience de l'équipe chirurgicale : elles se discutent en réunion de concertation pluridisciplinaire."},{"i":"index-de-carcinose-peritoneale-pci","t":"Index de carcinose péritonéale (PCI)","x":"L'abdomen est divisé en 13 régions (9 régions abdomino-pelviennes et 4 régions du grêle) ; chaque région reçoit un score de 0 à 3 selon la taille des lésions (0 : aucune ; 1 : ≤ 0,5 cm ; 2 : 0,5 à 5 cm ; 3 : > 5 cm ou confluentes). Score total de 0 à 39 ; c'est une mesure chirurgicale que le scanner sous-estime, surtout pour le grêle et le mésentère."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Pour chaque territoire : présence et taille des implants ; insister sur les sites qui modifient la stratégie (mésentère, hile hépatique, séreuses digestives, coupoles, ganglions sus-rénaux, plèvre)."}]},{"t":"Carcinose péritonéale : pièges diagnostiques","n":"Pièges diagnostiques","u":"carcinose/pieges-diagnostiques.html","c":"Carcinose péritonéale","b":"l'atteinte sous-capsulaire hépatique par « scalloping » n'est pas une métastase parenchymateuse, et le scanner a des limites : miliaire, mésentère, remaniements après traitement.","s":[{"i":"atteinte-sous-capsulaire-hepatique","t":"Atteinte sous-capsulaire hépatique","x":"Implants de surface qui festonnent le contour du foie (« scalloping »), notamment le long du ligament falciforme. À distinguer d'une métastase parenchymateuse, entourée de parenchyme : la distinction change le stade (IIIC contre IVB)."},{"i":"fausses-carcinoses","t":"Fausses carcinoses","x":"Splénose : nodules de tissu splénique après splénectomie ou traumatisme, de même densité que la rate. Diverticulose colique : ne pas prendre un diverticule pour un implant. Ganglions mésentériques normaux, à ne pas confondre avec une carcinose mésentérique."},{"i":"limites-du-scanner","t":"Limites du scanner","x":"Miliaire carcinomateuse : implants infracentimétriques souvent invisibles. Carcinose mésentérique et du grêle, souvent sous-estimée. Remaniements postopératoires ou après chimiothérapie, difficiles à distinguer d'un résidu tumoral."},{"i":"dans-le-compte-rendu","t":"Dans le compte rendu","x":"Préciser les lésions douteuses et leur incertitude plutôt que de trancher à tort ; mentionner les zones difficiles à analyser (mésentère, grêle)."}]}];
